globalThis.TerminusQuestScript = {"records":[{"line":117,"body":[{"speaker":"Rheed","condition":"","expression":"feliz","text":"Aí está você. Chegue mais perto; guardamos um lugar. Eu ia contar justamente a história de alguém que quase não chegou."}]},{"line":119,"body":[{"speaker":"Criança","condition":"— escolha","text":""}]},{"line":121,"speaker":"Criança","choice":"Quem não chegou?","expression":"confuso","response":[{"speaker":"Rheed","condition":"","expression":"feliz","text":"Ghork. Guardem esse nome, todos vocês. Ele ia adorar saber que eu pedi."}],"question":false},{"line":122,"speaker":"Criança","choice":"Espera... essa história tem um final triste?","expression":"triste","response":[{"speaker":"Rheed","condition":"","expression":"neutro","text":"Tem seus momentos difíceis. Fique por perto, e vamos passar por eles juntos. Mas nada de espiar o final. Acabei de abrir o frasco."}],"question":false},{"line":124,"body":[{"speaker":"Rheed","condition":"","expression":"neutro","text":"Ghork tinha vindo de longe, de Daratrine. Trabalho, um novo começo, alguém que cuidasse da perna ferida... Terminus devia ter tudo isso. Mas, quando chegou, mal conseguia respirar."}]},{"line":128,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Eu consigo... só preciso de um instante..."}]},{"line":130,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Calma. Não tente levantar. Olhe para mim, aqui."}]},{"line":132,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Eu cheguei...? Aqui é Terminus?"}]},{"line":134,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"É. Você chegou. Continue olhando para mim, Ghork. Agora deixe o trabalho comigo."}]},{"line":138,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Bom... eu tinha planejado uma primeira impressão melhor."}]},{"line":140,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Eu já me contento com uma que você sobreviva para contar. Guarde o discurso, está bem? Mal recuperou o fôlego."}]},{"line":142,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Foi você que... Você me salvou?"}]},{"line":144,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Salvei. E você ainda está sob meus cuidados. Nada de começar a me agradecer saindo da cama."}]},{"line":153,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Olhem estes dois mapas. Supostamente da mesma mina, mas não parecem concordar. Os relatos também não ajudam muito. Estou disposta a financiar uma investigação completa, mas antes preciso saber quem é capaz de entender isso."}]},{"line":155,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Então quer que a gente entre lá e veja qual mapa está certo?"}]},{"line":157,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Ainda não. Primeiro vou escolher uma guilda. Por enquanto, trabalhem com os mapas e as fontes que podemos consultar aqui fora. Mostrem o que conseguem descobrir antes de alguém pôr os pés nas galerias."}]},{"line":159,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"E mostrem como pretendem tirar sua gente de lá depois. De preferência, inteira."}]},{"line":161,"body":[{"speaker":"Borun","condition":"","expression":"feliz","text":"Também gosto bastante dessa parte. Fica difícil aproveitar o pagamento quando a gente não volta."}]},{"line":163,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Antes de começarmos: todas as guildas recebem as mesmas cópias, correto?"}]},{"line":165,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Correto. O pagamento é alto, e o contrato é exclusivo. Uma guilda responde pelo levantamento inteiro. Não vou dividir o trabalho entre três planos concorrentes."}]},{"line":167,"body":[{"speaker":"Ghork","condition":"— perguntas livres","text":""}]},{"line":169,"speaker":"Ghork","choice":"Não seria mais fácil contratar alguém que já andou por essas minas?","expression":"confuso","response":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Cada pessoa conhece um pedaço. Preciso de alguém que junte esses relatos e me diga onde faltam informações. Até agora, ninguém conseguiu me mostrar o quadro completo."}],"question":true},{"line":170,"speaker":"Ghork","choice":"E a guilda poderia usar uma parte do pagamento para se preparar para o campeonato?","expression":"neutro","response":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Depois de ganhar sua parte, a guilda decide o que fazer com ela. Eu estou pagando por um levantamento das minas, Ghork. Se quiser um título na arena também, vai ter de conquistá-lo por conta própria."}],"question":true},{"line":171,"speaker":"Ghork","choice":"Posso ouvir o que as três guildas pretendem fazer antes de escolher uma?","expression":"confuso","response":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Pode. Ouvir uma proposta não obriga você a aceitá-la. Mas, quando vier a esta mesa e se comprometer a executar uma delas, estará entrando naquela guilda. Tenha certeza antes de decidir."}],"question":true},{"line":173,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Tragam suas fontes e mostrem como vão conferir os mapas. Se algo continuar incerto, digam. Cada guilda será ouvida. Ghork, conheça o trabalho delas antes de escolher de qual vai fazer parte."}]},{"line":182,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Você anda olhando bastante para o coliseu. Já ouviu falar do campeão de lá?"}]},{"line":184,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"O nome dele está em todo lugar. Desde que cheguei, vi mais vezes que o meu."}]},{"line":186,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Então vou contar uma coisa que não está nos cartazes. Torvak lutou ao lado de Orcquius e Glavius."}]},{"line":188,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Orcquius e Glavius? Os dois?"}]},{"line":190,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Os três eram do mesmo time. Isso acabou. Cada um seguiu seu caminho."}]},{"line":192,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Se eu vencesse alguém que lutou ao lado de Orcquius... ele ia ter de..."}]},{"line":194,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Você teria vencido Torvak, Ghork. Já é bastante coisa para querer. Conheça o homem antes de transformar essa luta num recado para o general."}]},{"line":198,"body":[{"speaker":"Torvak","condition":"","expression":"feliz","text":"Este homem carregou dois dos nossos até a saída! Se vão contar como voltamos para casa, tratem de contar a parte dele também."}]},{"line":202,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Torvak? É verdade que você lutou ao lado de Orcquius e Glavius?"}]},{"line":204,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"É verdade. Pelo jeito, você veio de Daratrine?"}]},{"line":206,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vim. Meu nome é Ghork."}]},{"line":208,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Ghork. E agora está andando com aquelas guildas que acham que podem me ensinar a administrar uma arena."}]},{"line":210,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":212,"speaker":"Ghork","choice":"Vou tentar chegar à final. Quero enfrentar você lá.","expression":"neutro","response":[{"speaker":"Torvak","condition":"","expression":"feliz","text":"Então tem um bocado de trabalho antes da nossa próxima conversa. Melhor começar."}],"question":false},{"line":213,"speaker":"Ghork","choice":"O que aconteceu com seu antigo time? Por que vocês se separaram?","expression":"confuso","response":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"A equipe acabou. Essa parte da minha vida não está aberta a perguntas."}],"question":false},{"line":215,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Se eu conseguir chegar à final... vai lembrar do meu nome, não vai?"}]},{"line":217,"body":[{"speaker":"Torvak","condition":"","expression":"feliz","text":"Rask vai gritar seu nome para o coliseu inteiro. Acredite, não vai precisar me lembrar."}]},{"line":226,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"Ghork, não é? Acabei ouvindo a conversa. Chegar à final é uma bela ambição. A parte difícil vai ser acompanhar o ritmo dos treinos."}]},{"line":228,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Deixe eu adivinhar. Você vende alguma coisa que ajuda?"}]},{"line":230,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"Preparo fórmulas para quem já não consegue acompanhar o esforço que o trabalho exige. Alguns puderam voltar a ganhar a vida. Achei que gostaria de saber."}]},{"line":232,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Já estou tratando essa perna. Não quero atrapalhar o tratamento."}]},{"line":234,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"Claro. Percebi que ainda está se recuperando. Por isso vim falar agora, antes que a pressão para acompanhar os outros acabe em outro ferimento."}]},{"line":236,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":238,"speaker":"Ghork","choice":"Antes de falar em tomar isso... o que tem nesse frasco?","expression":"confuso","response":[{"speaker":"Savel","condition":"","expression":"neutro","text":"A preparação dependeria do seu estado. Eu não entregaria uma dose para depois deixar você por sua conta. Seria preciso acompanhar o tratamento."},{"speaker":"Ghork","condition":"","expression":"neutro","text":"Está bem, mas você ainda não me disse o que tem dentro."},{"speaker":"Savel","condition":"","expression":"neutro","text":"Passe no boticário. Lá podemos conversar com calma sobre suas dúvidas."}],"question":false},{"line":239,"speaker":"Ghork","choice":"Por enquanto, vou continuar com o tratamento que já tenho. Está ajudando.","expression":"neutro","response":[{"speaker":"Savel","condition":"","expression":"neutro","text":"Como preferir. Se sentir que precisa de algo mais, já sabe onde procurar."}],"question":false},{"line":241,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"Boa sorte para conquistar sua vaga, Ghork. É uma pena ver alguém capaz passar despercebido por falta de uma única oportunidade."}]},{"line":243,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Me deem uma. O resto eu faço."}]},{"line":254,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Você já pode praticar movimentos curtos, com alguém acompanhando. Se essa perna falhar, pare. Eu sei que está se sentindo melhor. Isso não significa que pode ignorar qualquer dor e continuar."}]},{"line":256,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu quero lutar, Virmura. Mas também gostaria de voltar andando depois."}]},{"line":258,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Ótimo. Diga isso à Guedra. Ela sabe preparar um treino que sirva para você, em vez de obrigar você a caber no exercício dos outros."}]},{"line":262,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Sou Guedra. Vamos ver como você se move. Vou avançar; mostre como recuaria. Ainda não estamos tentando ganhar nada."}]},{"line":264,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"E eu tinha planejado um primeiro ataque tão magnífico..."}]},{"line":266,"body":[{"speaker":"Guedra","condition":"","expression":"feliz","text":"Guarde para depois. Primeiro me mostre uma fuga magnífica."}]},{"line":270,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Você já pode enfrentar alguém sem depender de um resgate. Aprendeu a deixar espaço para recuar. Agora precisa reconhecer quando usá-lo, mesmo que queira continuar lutando."}]},{"line":272,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":274,"speaker":"Ghork","choice":"Meu primeiro adversário pode ser alguém que não seja o maior lutador da arena? Só para começar com calma.","expression":"feliz","response":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Pode. Escolher uma luta que consegue enfrentar faz parte do treino. Não precisa se arriscar só para impressionar alguém."}],"question":false},{"line":275,"speaker":"Ghork","choice":"E, se eu deixar alguém fechar minha saída, pelo menos vou saber onde errei.","expression":"neutro","response":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Vai saber. Depois vai praticar de novo. Entender o erro é um começo; fazer os pés se moverem de outro jeito exige treino."}],"question":false},{"line":291,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Está vendo esta caixa? Ataduras limpas de um lado, as que precisam de lavagem do outro. Pode fazer sentado. Se cansar, me avise."}]},{"line":293,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E se eu ajudar... posso ficar aqui? Ainda não tenho onde morar."}]},{"line":295,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Pode. Um lugar para ficar, em troca do trabalho que conseguir fazer enquanto melhora. Esse é o acordo. Ter salvado sua vida não faz de você meu devedor."}]},{"line":297,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":299,"speaker":"Ghork","choice":"Quero ajudar. Só não quero prometer mais do que essa perna vai deixar.","expression":"triste","response":[{"speaker":"Virmura","condition":"","expression":"feliz","text":"Então comece pela caixa. Se precisar descansar, ela continua aqui. Ataduras não têm o costume de fugir."}],"question":false},{"line":300,"speaker":"Ghork","choice":"Então prepare-se para ver uma separação de ataduras digna de entrar para a história.","expression":"feliz","response":[{"speaker":"Virmura","condition":"","expression":"feliz","text":"As limpas numa pilha separada, por favor. Vamos conseguir isso antes de encomendar sua estátua."}],"question":false},{"line":304,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Então vocês não cuidam só de quem chega aqui? Também saem para buscar os feridos?"}]},{"line":306,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Saímos. E alguém precisa encontrar o caminho para trazer todos de volta. Braços fortes não adiantam muito se a equipe inteira se perder."}]},{"line":308,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu quero entrar no campeonato. E ganhar. Se eu voltar com esse título... quero ver dizerem outra vez que não sirvo para nada."}]},{"line":310,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Pode me contar tudo sobre esse título enquanto separa. As ataduras não vão se arrumar sozinhas, campeão."}]},{"line":314,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Lala me deu esse colar para a gente continuar conversando. Disse que alguém que sabe usar mana pode recarregar. Você conseguiria...?"}]},{"line":316,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Me dê aqui. Isso eu consigo. Depois fale com ela e conte que chegou. Imagino que queira ouvir de você."}]},{"line":318,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Ghork! Até que enfim! Eu estava... espera. Onde você está? O que é isso atrás de você?"}]},{"line":320,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":322,"speaker":"Ghork","choice":"É uma enfermaria. A perna estava pior do que eu pensava, Lala.","expression":"triste","response":[{"speaker":"Lala","condition":"","expression":"confuso","text":"Uma enfermaria? Ghork, por que não falou logo? Tem alguém aí com você?"}],"question":false},{"line":323,"speaker":"Ghork","choice":"Encontrei uma curandeira. Virmura. Ela está cuidando de mim.","expression":"neutro","response":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Ai, ainda bem. Está bem. Me conta o que aconteceu, desde o começo."}],"question":false},{"line":325,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Quase não cheguei vivo. Virmura salvou minha vida. Vai me deixar ficar enquanto melhoro, e eu ajudo no que conseguir."}]},{"line":327,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Então deixe ela cuidar de você, por favor. Depois você me conta da cidade. Dam me passou uma lista: como está sua perna, onde está dormindo e se está comendo. Nessa ordem. Pelo visto, não posso improvisar."}]},{"line":329,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Diga que estou sendo muito bem vigiado. Nem consegui impressionar a curandeira com as ataduras ainda."}]},{"line":331,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Vou dizer que tem alguém cuidando de você. Ser vigiado nunca impediu você de se meter em confusão."}]},{"line":335,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Tenho duas entregas aqui perto que você pode fazer: uma no mercado, outra no coliseu. Escolha por qual começar. E, se precisar descansar, pare. Os pacotes podem esperar junto com você."}]},{"line":344,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Podemos usar este registro de resgate. Cubra o nome do paciente antes de copiar. Meruna precisa conhecer o caminho, não saber de quem eram os ferimentos que nos levaram até lá."}]},{"line":346,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Olhe isto: \"Da passagem estreita até o ponto de troca da maca.\" Tem uma distância, mas... começaram a contar de onde?"}]},{"line":348,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Essa é uma pergunta. Outra: passaram andando por esse espaço ou levaram uma maca? Não quero descobrir a diferença com um paciente em cima."}]},{"line":350,"body":[{"speaker":"Ghork","condition":"— investigação, ambas disponíveis","text":""}]},{"line":352,"speaker":"Ghork","choice":"Vou marcar os pontos de referência. Pelo menos assim dá para ver de que parte do caminho estão falando.","expression":"neutro","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Só os que realmente descreveram. Se precisar adivinhar, deixe uma pergunta. Podemos procurar a resposta depois; um erro que parece certeza só atrapalha."}],"question":true},{"line":353,"speaker":"Ghork","choice":"Quem carregava a maca? Isso não mudaria o tempo do percurso?","expression":"confuso","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Uma equipe de resgate. E mudaria, sim. Carregar alguém em grupo é diferente de andar sozinho. Não use o passo de uma pessoa para calcular o deles."}],"question":true},{"line":357,"body":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Posso ficar com uma cópia? Preciso pôr ao lado dos mapas e acompanhar o caminho como está descrito."}]},{"line":359,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Virmura autorizou compartilhar o trajeto. Tirei os nomes, para a história dos pacientes não ir junto."}]},{"line":361,"body":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Obrigada. Leve estas anotações para ela. Consigo comparar os marcos, mas preciso confirmar de onde partiram para essas distâncias fazerem sentido."}]},{"line":365,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Depois de tudo isso, só podemos garantir um trecho? Eu esperava ter mais para mostrar à Meruna."}]},{"line":367,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Preferia ficar na frente dela e fingir que conhece a mina inteira? Podemos mostrar como conferimos esta parte. Nisso ela pode confiar."}]},{"line":369,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Não. Quero que ela acredite na gente. Vou mostrar o trabalho que deu chegar até aqui."}]},{"line":380,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"E se levássemos todo mundo que entende de resgate para a demonstração? Meruna ia ver quanta ajuda esta guilda pode oferecer."}]},{"line":382,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"E, se precisasse de uma curandeira depois, encontraria uma bela enfermaria vazia."}]},{"line":384,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"É. Não pensei nisso. Quantos podemos levar sem fazer falta aqui?"}]},{"line":386,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Uma equipe pequena basta para mostrar como trabalhamos. Cada um com uma tarefa. Depois fazemos a conta direito: quem vai a campo e quem mantém este lugar funcionando."}]},{"line":388,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":390,"speaker":"Ghork","choice":"Vou preparar uma escala. Quem sai, quem fica e do que cada pessoa vai cuidar.","expression":"neutro","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Ótimo. Nada de pôr a mesma pessoa nas duas listas. Eu adoraria aprender esse truque, mas ainda não consegui."}],"question":false},{"line":391,"speaker":"Ghork","choice":"Deixe eu explicar à Meruna. Ela precisa saber por que não vamos levar a guilda inteira.","expression":"neutro","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Explique. Só não ofereça o trabalho da enfermaria de graça para melhorar a proposta. Alguém precisa pagar pelo atendimento que continua aqui."}],"question":false},{"line":395,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Leve este pedido a Durn. Ele tem uma maca e suportes para a demonstração. A equipe vai carregar. Seu trabalho é conferir se vieram todas as peças."}]},{"line":399,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Vão pegar emprestado para o teste? Está bem. Depois me devolvam cada peça. Inclusive as pequenas que o pessoal costuma esquecer."}]},{"line":401,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Entendido. Podemos conferir juntos antes de a equipe levar? Quero saber pelo que estou respondendo."}]},{"line":403,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Podemos. Fique onde eu consiga ver seu rosto quando falar. Vou mostrar como as peças encaixam, e você pergunta o que precisar."}]},{"line":407,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Depois de cuidar da enfermaria e da equipe de campo... ainda vai sobrar gente e tempo para o campeonato?"}]},{"line":409,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Isso faz parte do planejamento. O contrato ajudaria a pagar o trabalho. Não vai espremer mais uma hora no dia, por mais bonito que você peça."}]},{"line":411,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Já ouvi umas promessas bem confiantes sobre isso. Ainda estou esperando alguém cumprir."}]},{"line":422,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Sua vez de orientar a passagem da maca. A equipe vai seguir o que você disser. Dê tempo para entenderem antes de se mover."}]},{"line":424,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Um pouco para a esquerda, depois... espera, a minha esquerda. Desculpem. Assim não ajuda, não é?"}]},{"line":428,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Diga onde a maca precisa chegar. Escolha alguma coisa que todos na sala consigam ver."}]},{"line":430,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":432,"speaker":"Ghork","choice":"Ao lado da porta. Vou usar a sala como referência, para ninguém precisar descobrir para que lado estou virado.","expression":"neutro","response":[{"speaker":"Virmura","condition":"","expression":"feliz","text":"Melhor. Tente de novo. A gente ensinou a equipe a carregar uma maca, não a ler sua cabeça."}],"question":false},{"line":433,"speaker":"Ghork","choice":"Posso marcar onde cada um deve parar? Assim eles mesmos podem conferir.","expression":"confuso","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Pode. Dê uma volta e confira se cada pessoa consegue ver a marca do lado em que está."}],"question":false},{"line":437,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Ainda bem que não tem ninguém nessa maca. Eu não queria aprender isso com alguém esperando atendimento."}]},{"line":439,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"É por isso que estamos praticando. Anote o que mudou enquanto ainda lembra bem. Meruna precisa ver a correção, não só a tentativa."}]},{"line":443,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Como se saiu? Alguma peça entortou ou saiu do lugar com o peso?"}]},{"line":445,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"A maca estava boa. Minhas instruções é que saíram meio tortas. Arrumamos isso antes de continuar."}]},{"line":447,"body":[{"speaker":"Durn","condition":"","expression":"feliz","text":"Então o teste serviu para alguma coisa. Deixe eu contar... sim, está tudo aqui. Obrigado por devolver direito."}]},{"line":456,"body":[{"speaker":"Ghork","condition":", se escolheu registro em A3","expression":"neutro","text":"A escala está pronta. Conferi as duas listas: ninguém ficou encarregado de estar em campo e junto a um leito da enfermaria ao mesmo tempo."}]},{"line":458,"body":[{"speaker":"Ghork","condition":", se escolheu explicação em A3","expression":"neutro","text":"Então vou explicar por que precisamos de gente aqui e em campo. É por aí que quero começar."}]},{"line":460,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Ótimo. Junte com o registro de resgate e as instruções que testou. Meruna precisa ver o que conferimos. E, se alguém voltar ferido, precisa saber que deixamos gente aqui para cuidar."}]},{"line":462,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"O que eu digo quando ela apontar as partes do mapa que ainda não sabemos explicar?"}]},{"line":464,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Que não sabemos. Marque bem. Quem entrar lá merece ver onde faltam informações antes de ter de descobrir no escuro."}]},{"line":466,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Se eu ficar do seu lado naquela reunião, Borun e Sevrak vão perder o contrato. Depois de tudo que fizeram por mim..."}]},{"line":468,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Sim. Eles também precisam desse dinheiro, e não vão gostar. Não vou fingir o contrário para convencer você a entrar. Pense nisso antes de me dar sua palavra."}]},{"line":472,"speaker":"Ghork","choice":"Quero conhecer outras propostas.","response":[{"speaker":"Virmura","condition":"","text":"Vá. Esta continua disponível até você assumir outro compromisso."}],"question":false},{"line":473,"speaker":"Ghork","choice":"Quero defender esta estratégia.","response":[],"question":false},{"line":487,"body":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"Ataduras e material de lavagem para Virmura. Coloquei tudo nesta bolsa. Confira antes de sair; é mais fácil corrigir um erro enquanto você está aqui."}]},{"line":489,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Prefiro descobrir agora a ter de explicar uma bolsa vazia para Virmura. Vamos ver..."}]},{"line":493,"body":[{"speaker":"Assaltante","condition":"","expression":"raiva","text":"A bolsa. Deixa no chão e pode continuar andando."}]},{"line":495,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"São ataduras. Vão fazer curativo um no outro? Escolheram a bolsa errada."}]},{"line":499,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Ghork! Aquele carrinho vazio... empurre para cá. Agora!"}]},{"line":503,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Você sabia meu nome. Como sabia meu nome?"}]},{"line":505,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Ouvi quando você pegou a bolsa. Depois aqueles dois largaram o que estavam fazendo e seguiram você. Achei que valia ficar de olho."}]},{"line":507,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":509,"speaker":"Ghork","choice":"Eu não percebi nada. Só quando fecharam a passagem.","expression":"triste","response":[{"speaker":"Borun","condition":"","expression":"neutro","text":"É fácil não perceber quando ainda está tentando se achar por aqui. Agora você já viu uma vez. Na próxima, olhe o que as pessoas fazem, não só o sorriso que mostram."}],"question":false},{"line":510,"speaker":"Ghork","choice":"Achei que estavam esperando espaço para passar. Tinha tanta gente.","expression":"confuso","response":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Eu também achei, no começo. Mas abriu um espaço bem na frente deles e nenhum se moveu. Não estavam esperando passagem. Estavam esperando você."}],"question":false},{"line":512,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Obrigado. Por me tirar de lá e por ficar para explicar. Eu ia continuar tentando entender o que não percebi."}]},{"line":514,"body":[{"speaker":"Borun","condition":"","expression":"feliz","text":"Borun. Minha guilda se chama Caminhos Abertos. Tentamos fazer jus ao nome, até em manhãs como esta. Venha, acompanho você até passarmos dessa confusão."}]},{"line":516,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Caminhos Abertos... vocês entram no campeonato? Estou tentando entender como funciona."}]},{"line":518,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Entramos. Encontrar uma equipe é uma parte. Achar onde treinar é outra, com o campeão querendo os melhores horários para os dele. Conheça quem vai trabalhar com você antes de se comprometer."}]},{"line":522,"body":[{"speaker":"Virmura","condition":"","expression":"confuso","text":"Aí está você. Demorou mais do que eu esperava. O que houve?"}]},{"line":524,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Dois homens tentaram levar os materiais. Borun me ajudou a sair do corredor. Não perdi a bolsa, está vendo? Está tudo aqui."}]},{"line":526,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Ponha a bolsa aí e sente um pouco. Estou vendo que os materiais estão bem. Estou perguntando de você."}]},{"line":535,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Este registro acompanha a carga, não a mim. Se olhar só essa data de chegada, parece que levei a carroça até o fim da galeria."}]},{"line":537,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Você não foi até o fim com ela?"}]},{"line":539,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Só até onde a carroça cabia. Dali em diante, entreguei a carga. O resto do caminho foi outra pessoa que fez, a pé."}]},{"line":541,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Entendeu por que eu queria que ouvisse a Pirka? O registro não conta onde ela deixou de acompanhar a carga."}]},{"line":543,"body":[{"speaker":"Ghork","condition":"— investigação","text":""}]},{"line":545,"speaker":"Ghork","choice":"Onde exatamente você passou a carga adiante? Dá para achar esse ponto no mapa?","expression":"confuso","response":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Tem uma descrição aqui. Copie também, não só o nome do lugar. Já perdi uma tarde procurando um ponto que todo mundo sabia nomear e ninguém sabia indicar."}],"question":true},{"line":546,"speaker":"Ghork","choice":"Você chegou a ver o caminho depois desse ponto, mesmo sem levar a carga até lá?","expression":"confuso","response":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Não. Minha parte termina ali. Se alguém disser que vi mais alguma coisa, traga aqui. Eu mesma quero ouvir essa história."}],"question":true},{"line":550,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Então o registro fez sua parte da viagem parecer maior. Vou marcar onde você realmente parou."}]},{"line":552,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Ótimo. Agora sabemos sobre que trecho perguntar a ela e onde precisamos procurar outra pessoa."}]},{"line":554,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Falando em viagem, tenho outra carga para cuidar. Terminamos por aqui?"}]},{"line":556,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Quase. Posso levar uma cópia para Elune? Ela vai precisar comparar com os mapas."}]},{"line":558,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Leve esta. O original fica comigo; preciso dele para conferir a próxima carga."}]},{"line":569,"body":[{"speaker":"Elune","condition":"","expression":"confuso","text":"Achei que Borun vinha com você. Trouxe as perguntas ou ficaram com ele também?"}]},{"line":571,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Trouxe. Só estava esperando que ele viesse para pensar nas que eu deixei passar."}]},{"line":573,"body":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Bom, você está aqui. Quero ouvir as suas. Podemos começar por elas."}]},{"line":575,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":577,"speaker":"Ghork","choice":"Primeiro, quero separar o que Pirka viu do que contaram a ela depois.","expression":"neutro","response":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Então não perca esse ponto de troca. O relato dela leva até ali. Depois, precisamos de alguém que tenha seguido pelo caminho."}],"question":false},{"line":578,"speaker":"Ghork","choice":"Quero que alguém leia isto depois e entenda como chegamos à resposta, sem ter de acreditar só na minha palavra.","expression":"neutro","response":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Então ponha uma fonte ao lado de cada informação. Se alguma coisa não bater, saberão onde conferir, sem precisar procurar você primeiro."}],"question":false},{"line":582,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Aí está você. Uma carga me prendeu na descarga. Como foi com Elune?"}]},{"line":584,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Deu certo. Mas eu fiquei esperando você. Podia ter mandado um recado."}]},{"line":586,"body":[{"speaker":"Borun","condition":"","expression":"triste","text":"Devia ter mandado. Vou combinar os horários com Pirka e avisar quando mudarem."}]},{"line":588,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Ótimo. Porque eu não ia fingir que você me deixou lá para me ensinar a ser independente."}]},{"line":590,"body":[{"speaker":"Borun","condition":"","expression":"feliz","text":"Não finja mesmo. Uma desculpa tão boa dessas, sou capaz de acabar acreditando."}]},{"line":599,"body":[{"speaker":"Pirka","condition":"","expression":"raiva","text":"Levaram as cordas e estacas da nossa demonstração. Dois homens no corredor: um saiu com o fardo enquanto o outro impedia a gente de ir atrás."}]},{"line":601,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Dois, agindo juntos? Será que são os mesmos que me cercaram?"}]},{"line":603,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Parece. Antes de ir atrás, descubra como sair daquele corredor. Você já pode tentar uma luta, mas isso não significa deixar os dois prenderem você de novo."}]},{"line":605,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu lembro de como foi. Vou buscar a carga da Pirka, não provar que nada pode me machucar."}]},{"line":609,"body":[{"speaker":"Ghork","condition":"— abordagem","text":""}]},{"line":611,"speaker":"Ghork","choice":"Vocês levaram o fardo da Pirka. Devolvam, e podemos encerrar isso aqui.","expression":"neutro","response":[{"speaker":"Assaltante","condition":"","expression":"feliz","text":"Olha quem voltou. Veio sem o velho para se esconder atrás dele?"}],"question":false},{"line":612,"speaker":"Ghork","choice":"Da outra vez eram ataduras. Finalmente acharam uma bolsa que vale roubar ou pegam qualquer coisa que estiver perto?","expression":"feliz","response":[{"speaker":"Assaltante","condition":"","expression":"raiva","text":"Quer o fardo ou quer perder os dentes?"}],"question":false},{"line":614,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"O fardo. Foi para isso que eu vim."}]},{"line":620,"body":[{"speaker":"Assaltante","condition":"","expression":"triste","text":"Está bem! Leva! Não vou apanhar mais por um saco de cordas."}]},{"line":622,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Então parem de levar o que não é de vocês."}]},{"line":626,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"É a nossa marca no fardo. Ótimo. Ponha aqui; quero ver o que deixaram dentro."}]},{"line":628,"body":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"Cordas, estacas... está tudo aqui. Este é o recibo, para ninguém precisar ficar só na nossa palavra de que chegou."}]},{"line":630,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Posso ficar com uma cópia para Borun? Ele vai querer saber que recuperamos tudo."}]},{"line":632,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Já que está aqui, me mostre as instruções. Eu preciso conseguir seguir sem você ao meu lado explicando cada curva."}]},{"line":636,"body":[{"speaker":"Borun","condition":"","text":"“Eles conseguiram fechar os dois lados. Na próxima aproximação, guarde a passagem por onde vai sair.”"},{"speaker":"Ghork","condition":"","text":"“Vou recuperar o fardo. Primeiro preciso recuperar o fôlego.” O jogador pode preparar-se, visitar o Coreto entre cenas e voltar; sem pagamento, perda de outro item ou recrutar alguém. Na revanche,"},{"speaker":"Assaltante","condition":"","text":"“Você de novo?”"},{"speaker":"Ghork","condition":"","text":"“Vocês ainda estão com a carga.” Repetir apenas o combate, não a abertura ou as recompensas."}]},{"line":640,"body":[{"speaker":"Borun","condition":"","expression":"confuso","text":"Está com o recibo. E a carga? Veio tudo?"}]},{"line":642,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Pirka e Jorvi conferiram cada peça. Também arrumei as instruções do corredor. Percebi que tinha escrito para quem já conhecia o caminho."}]},{"line":644,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"É fácil cair nessa. Vamos lá, leia a versão nova."}]},{"line":646,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Passe pela área de descarga, ao lado da banca. Isso alguém novo consegue achar. \"Pelo caminho de sempre\" só ajuda quem já tem um caminho de sempre."}]},{"line":655,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Vamos pôr o relato da Pirka ao lado do registro da carga e mostrar as instruções que outra pessoa conseguiu seguir. É esse trabalho que quero financiar com o contrato: gente saindo, olhando direito e trazendo algo útil para a próxima equipe."}]},{"line":657,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"E usaria parte do dinheiro para resgates. Você falou disso antes."}]},{"line":659,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Usaria. Tem contratante muito interessado no caminho de ida que só pergunta pelo de volta quando alguém não aparece."}]},{"line":661,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E se Meruna disser que os relatos estão incompletos demais para confiar?"}]},{"line":663,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Mostre exatamente o que pudemos conferir e o que ainda precisa de uma visita. Os relatos estão incompletos. Blefar não melhora isso. E, se prometer que nunca erramos, vou ter de interromper você."}]},{"line":665,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Virmura salvou minha vida. Sevrak também me protegeu. É estranho falar em escolher entre vocês."}]},{"line":667,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Pode ser grato aos dois e ainda escolher seu trabalho. Mas eles têm guildas para cuidar, assim como eu. Não espere que sua gratidão faça os dois saírem do caminho."}]},{"line":671,"speaker":"Ghork","choice":"Vou ouvir as outras propostas.","response":[{"speaker":"Borun","condition":"","text":"Ouça. Depois volte com uma decisão que consiga explicar."}],"question":false},{"line":672,"speaker":"Ghork","choice":"Quero defender este plano.","response":[],"question":false},{"line":686,"body":[{"speaker":"Veterano","condition":"","expression":"raiva","text":"Levanta. De novo. Vai passar o treino inteiro no chão?"}]},{"line":688,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Olhe o ombro dele! Ele ergue antes de atacar. Quando subir, saia do alcance. Não espere pelo golpe."}]},{"line":692,"body":[{"speaker":"Veterano","condition":"","expression":"raiva","text":"Então ajudou ele a escapar de um. Acha que consegue fazer melhor? Venha mostrar."}]},{"line":696,"body":[{"speaker":"Sevrak","condition":"","expression":"raiva","text":"Basta. Seu treino acabou."}]},{"line":698,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Eu só estava tentando ajudar o rapaz. Não queria..."}]},{"line":700,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Eu vi o que aconteceu. Pode parar de se justificar e explicar o movimento. O que percebeu?"}]},{"line":702,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":704,"speaker":"Ghork","choice":"Ele se preparava do mesmo jeito toda vez. Depois que percebi, dava para saber quando vinha o próximo ataque.","expression":"neutro","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Enquanto o rapaz esperava ver o próprio golpe. Você deu a ele um sinal que permitia agir antes. Uma diferença útil."}],"question":false},{"line":705,"speaker":"Ghork","choice":"Alguém precisava dizer ao rapaz como escapar. Derrubar de novo não estava ensinando nada.","expression":"neutro","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"E você tinha mais a oferecer do que compaixão. Deu uma instrução que ele conseguiu usar. Mostre o que viu."}],"question":false},{"line":707,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"O ombro, ali. Mexia antes do resto do corpo. Quando o braço avançava, o aviso já tinha passado."}]},{"line":709,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Sevrak Vey. Dirijo uma escola em que vale a pena desenvolver esse tipo de observação. Já pensou no que poderia fazer com isso?"}]},{"line":711,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Ghork. E obrigado. Eu preferia não descobrir pessoalmente como é receber aquele golpe."}]},{"line":713,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Parece que tem uma entrega para terminar. Depois, venha conhecer a escola. Tenho muitos alunos que sabem copiar um movimento. Gostaria de ter mais que soubessem explicar."}]},{"line":717,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"São as ataduras de Virmura? Obrigado, pode entregar. Ela pediu confirmação, então leve este recibo para ela."}]},{"line":719,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Levo. Rask, aconteceu uma coisa na entrada. Um veterano tentou me bater durante o treino. Sevrak impediu, mas você precisa saber."}]},{"line":721,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Vou conversar com os envolvidos. Fez bem em me contar. E obrigado por trazer os materiais."}]},{"line":730,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Aqui estão as duas cópias. Digamos que coloquemos uma sobre a outra. O que isso permite concluir?"}]},{"line":732,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Que não dá mais para ler a de baixo."}]},{"line":734,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Uma descoberta indispensável. Agora, o que tornaria a comparação útil?"}]},{"line":736,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":738,"speaker":"Ghork","choice":"Precisaríamos conferir os pontos de referência primeiro. Senão podemos estar comparando desenhos de lugares diferentes.","expression":"neutro","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Então identifique os marcos e escreva como vai compará-los. Quero que outra pessoa consiga fazer isso sem você apontando para o papel."}],"question":false},{"line":739,"speaker":"Ghork","choice":"Uma diferença nos desenhos pode significar várias coisas. Não devíamos escolher uma explicação só porque foi a primeira que veio à cabeça.","expression":"confuso","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Concordo. Anote as possibilidades. Depois procure algo que possa conferir para eliminar uma delas. Uma lista de palpites é só o começo."}],"question":false},{"line":743,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Está esperando que eu descubra uma resposta que você já sabe?"}]},{"line":745,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Estou esperando para ver o que consegue sustentar. Dar uma conclusão sem as provas só ensinaria você a me repetir. Mostre como chega à sua."}]},{"line":754,"body":[{"speaker":"Elune","condition":"","expression":"confuso","text":"Sevrak mandou você com isto? O que ele quer conferir, o resultado?"}]},{"line":756,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Isso, e se você consegue seguir as etapas sem ele ao lado. Se precisar chamar o mestre para explicar cada linha, não escrevi muito bem."}]},{"line":758,"body":[{"speaker":"Elune","condition":"","expression":"confuso","text":"Então foi aqui que me perdi. \"Normalizar.\" O que devo fazer com o mapa quando chegar nessa palavra?"}]},{"line":760,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":762,"speaker":"Ghork","choice":"Entendi o problema. Vou escrever o que fazer, passo a passo, em vez de esconder tudo numa palavra.","expression":"neutro","response":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Obrigada. Agora posso tentar a mesma comparação que você fez, sem ter de adivinhar o que quis dizer."}],"question":false},{"line":763,"speaker":"Ghork","choice":"Vou incluir um exemplo explicado. E marcar que é só um exemplo, para ninguém confundir com medidas tiradas da mina.","expression":"neutro","response":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Ponha o aviso onde ninguém deixe de ver. Essas páginas são copiadas. Não quero uma medida inventada circulando sem a explicação."}],"question":false},{"line":767,"body":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Até aqui consigo acompanhar. Depois deste ponto, faltam informações. Não posso preencher os espaços só para terminar a página."}]},{"line":769,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Por favor, não preencha. Sevrak ia perguntar onde achei as informações que faltavam, e minha resposta seria bem constrangedora."}]},{"line":771,"body":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Ele não seria o único a perguntar."}]},{"line":784,"body":[{"speaker":"Iniciante","condition":"","expression":"triste","text":"Sevrak, aquele veterano não quer devolver seu estojo de treino. Diz que Ghork tem de ir buscar e explicar de novo o truque do ombro. Sem você por perto."}]},{"line":786,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Reter meu equipamento para forçar um confronto? Vou falar com Rask. O estojo tem de ser devolvido."}]},{"line":788,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Eu vou buscar. Se tem alguma coisa para dizer de mim, pode dizer na minha frente."}]},{"line":790,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Você já pode enfrentar um duelo supervisionado. Se aceitar lutar, exija um juiz. E tenha clareza do motivo. Meu orgulho ferido não é razão para você se arriscar."}]},{"line":794,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Mandou me chamar. Estou aqui. O que queria dizer?"}]},{"line":796,"body":[{"speaker":"Veterano","condition":"","expression":"raiva","text":"Quero ver se tem um lutador por trás de tanto conselho. Ou só sabe falar?"}]},{"line":798,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Pode descobrir depois de devolver o estojo. Ele pertence à escola."}]},{"line":800,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Entregue para mim. O estojo será devolvido, aconteça o que acontecer aqui. Ghork me avisou da agressão; eu devia ter impedido que isso continuasse. Se os dois querem lutar, usem a área de duelo. Eu mesmo vou supervisionar."}]},{"line":804,"body":[{"speaker":"Ghork","condition":"— resposta","text":""}]},{"line":806,"speaker":"Ghork","choice":"Queria saber se consigo lutar. Está bem. Vamos fazer isso direito.","expression":"neutro","response":[{"speaker":"Veterano","condition":"","expression":"raiva","text":"Vamos torcer para ter aprendido alguma coisa além de olhar ombros."}],"question":false},{"line":807,"speaker":"Ghork","choice":"Da outra vez eu estava olhando de fora. Vamos ver o que percebo de perto.","expression":"feliz","response":[{"speaker":"Veterano","condition":"","expression":"raiva","text":"Continue falando. Quero ver como fica esperto de costas no chão."}],"question":false},{"line":809,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Quando eu mandar parar, os dois param. Se um dos lutadores não puder continuar, a luta acaba ali. Entendido?"}]},{"line":815,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Parem! A luta acabou. Ghork venceu."}]},{"line":817,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Aquele rapaz aprendeu quando alguém deu uma chance. Você podia ter feito isso por ele, em vez de deixar com medo de levantar outra vez."}]},{"line":819,"body":[{"speaker":"Veterano","condition":"","expression":"raiva","text":"Já ganhou. Ainda tenho de ouvir sermão?"}]},{"line":821,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Não. Vou levar o estojo de volta para a escola. Já estou indo."}]},{"line":823,"body":[{"speaker":"Veterano","condition":"","text":"“Conselho não vence luta.”"},{"speaker":"Ghork","condition":"","text":"“Essa tentativa não venceu. Vou voltar.” O desafio permanece aberto, sem retirar o estojo já restituído ou legitimar a intimidação. Ghork pode preparar-se e pedir revanche sem pagar."},{"speaker":"Rask","condition":", na retomada","text":"“Mesmas condições. Se eu interromper, os dois param.” A quest aguarda a vitória no desafio aceito; não se torna uma derrota permanente da campanha."}]},{"line":827,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"O estojo voltou. Ótimo. Agora me diga como foi o duelo."}]},{"line":829,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Rask foi o juiz. Eu ganhei. Foi bom, mas... vencer não faz tudo que eu disse estar certo. Essa parte ainda precisa se sustentar sozinha."}]},{"line":831,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Uma diferença que vale guardar. Agora, seu relatório: você colocou o que não sabemos antes do que descobrimos. Por que começar por aí?"}]},{"line":833,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Porque alguém pode ler o resultado e parar ali. Não quero Meruna mandando gente para a mina com metade da explicação."}]},{"line":837,"speaker":"Ghork","choice":"Vou pôr o aviso ao lado da conclusão. Assim ela vê o que descobrimos e onde deixa de haver certeza.","expression":"neutro","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Tente. Se eu conseguir ler os dois sem procurar pela página, deve servir."}],"question":false},{"line":838,"speaker":"Ghork","choice":"Prefiro explicar primeiro o que não conseguimos descobrir. Depois mostro quanto ainda conseguimos conferir.","expression":"neutro","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Então esteja pronto para explicar isso à Meruna. Essa escolha de apresentação é sua. Não vou intervir para defendê-la por você."}],"question":false},{"line":847,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Meruna poderá conferir nosso trabalho por conta própria. É isso que oferecemos. Com o contrato, a escola pode ensinar mais pessoas a fazer o mesmo levantamento, em vez de depender do julgamento de uma só."}]},{"line":849,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"E o dinheiro mantém sua escola funcionando. Não se trata só dos mapas."}]},{"line":851,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Ela poderia ser sua escola também, Ghork. Se decidir entrar."}]},{"line":853,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Ainda não decidi. Quero deixar isso claro."}]},{"line":855,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Então também vou ser claro. Quero você trabalhando na investigação e se preparando para o campeonato. Vejo algo em você que vale desenvolver, mas entrar na escola significa trabalhar."}]},{"line":857,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E se eu encontrar um erro no seu método? Quer que eu aponte ou aprenda a fazer do seu jeito mesmo assim?"}]},{"line":859,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Mostre o erro. Dizer que discorda não basta, mas demonstrar uma falha é útil. Você deve exigir de mim o mesmo cuidado."}]},{"line":863,"speaker":"Ghork","choice":"Vou ouvir as outras guildas.","response":[{"speaker":"Sevrak","condition":"","text":"O procedimento fica disponível. Não confunda demora com comparação cuidadosa."}],"question":false},{"line":864,"speaker":"Ghork","choice":"Quero defender este método.","response":[],"question":false},{"line":880,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Ghork, você conheceu o trabalho dessas guildas. Agora preciso de uma resposta: qual proposta vai ajudar a executar?"}]},{"line":884,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"A de Virmura. Conferimos um trajeto de resgate com os mapas e depois testamos as instruções com uma maca. Sabemos quem vai a campo e quem fica para cuidar de quem precisa da guilda."}]},{"line":886,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Conferiram um trajeto de resgate. Uma mina tem um pouco mais do que isso. O que vão dizer à Meruna sobre o restante?"}]},{"line":888,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":890,"speaker":"Ghork","choice":"Que ainda precisa ser investigado. Está marcado na proposta. Não estamos pedindo que acredite que conferimos mais do que realmente conferimos.","expression":"neutro","response":[],"question":false},{"line":891,"speaker":"Ghork","choice":"É isso que o contrato vai pagar para investigar. O que mostramos hoje foi como vamos fazer. Já testamos o procedimento.","expression":"neutro","response":[],"question":false},{"line":893,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Consigo distinguir o que conferiram do que estão propondo. Ótimo. Virmura, inclua os custos da enfermaria no plano, junto com os da equipe de campo. Preciso ver o custo completo desse acordo."}]},{"line":897,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"A de Borun. Conferimos o registro da carga com Pirka, que fez o transporte. Separamos o que ela viu do que contaram a ela e depois demos as instruções a outra pessoa, para ver se conseguia seguir."}]},{"line":899,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"E quando alguém se machucar lá embaixo? O que acontece se esses relatos não bastarem para indicar como tirar a pessoa?"}]},{"line":901,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":903,"speaker":"Ghork","choice":"Anotamos o que falta antes de alguém entrar. Se não podemos confirmar uma saída, não marcamos como segura e torcemos para dar certo.","expression":"neutro","response":[],"question":false},{"line":904,"speaker":"Ghork","choice":"Então a equipe volta com essa pergunta sem resposta. Receber pelo trabalho não obriga ninguém a inventar o que não conseguiu descobrir.","expression":"neutro","response":[],"question":false},{"line":906,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Inclua esse limite no relatório. Borun, você fica responsável por conferir essas fontes em campo. Espero que o registro mostre o que realmente encontraram."}]},{"line":910,"body":[{"speaker":"Ghork","condition":", se C4 começou pelo limite","expression":"neutro","text":"Antes de mostrar o resultado, quero apontar o que não conseguimos verificar. Depois explico como conferimos o restante."}]},{"line":912,"body":[{"speaker":"Ghork","condition":", se C4 colocou a ressalva ao lado","expression":"neutro","text":"Escolho a proposta de Sevrak. Cada conclusão indica o que ainda não sabemos. Elune conseguiu repetir o método sem chamar o mestre para explicar, então você também pode conferir nosso trabalho."}]},{"line":914,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Instruções bem arrumadas não fazem um relato errado virar verdade. E se a pessoa que passou a informação tiver se enganado?"}]},{"line":916,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":918,"speaker":"Ghork","choice":"É por isso que cada informação tem uma fonte ao lado. Se alguma coisa não bater, sabemos onde voltar para conferir.","expression":"neutro","response":[],"question":false},{"line":919,"speaker":"Ghork","choice":"Então alguém pode seguir as etapas escritas e mostrar onde erramos. Não precisa aceitar só porque Sevrak ou eu dissemos.","expression":"neutro","response":[],"question":false},{"line":921,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Sevrak, quero esse registro mantido durante toda a investigação. Especialmente quando um resultado contrariar sua primeira explicação. Não pago a mais para manter coerência com um erro."}]},{"line":925,"body":[{"speaker":"Meruna","condition":"","text":"A proposta defendida demonstra capacidade suficiente para a investigação que estou contratando. O contrato fica com . O financiamento não será dividido."}]},{"line":929,"body":[{"speaker":"Virmura","condition":", se rejeitada","expression":"triste","text":"Eu contava com esse dinheiro para pôr uma equipe em campo. Sem ele, não posso ceder gente e materiais que fazem falta na enfermaria. Vamos disputar os próximos contratos. E vamos enfrentar vocês no campeonato."}]},{"line":931,"body":[{"speaker":"Borun","condition":", se rejeitado","expression":"triste","text":"Então vou ter de procurar outro trabalho para minha gente. Não vamos acompanhar sua expedição. E, quando chegar o campeonato, lembre que vamos competir contra você."}]},{"line":933,"body":[{"speaker":"Sevrak","condition":", se rejeitado","expression":"neutro","text":"Nossos instrutores e métodos continuam na escola. Terá a chance de ver do que abriu mão, Ghork. Imagino que o campeonato ofereça uma."}]},{"line":935,"body":[{"speaker":"Ghork","condition":"— escolha, depois das duas recusas","text":""}]},{"line":937,"speaker":"Ghork","choice":"Não esqueci o que fizeram por mim. Escolher esta guilda não significa que deixei de ser grato.","expression":"triste","response":[{"speaker":"Virmura","condition":"primeiro-rejeitado","expression":"triste","text":"Eu sei que é grato. Não estou pedindo que negue isso. Mas ainda tenho uma guilda cheia de gente dependendo de mim."},{"speaker":"Borun","condition":"primeiro-rejeitado","expression":"triste","text":"Eu sei, rapaz. Não acho que esqueceu. Mas, neste trabalho, ainda vamos seguir caminhos diferentes."},{"speaker":"Sevrak","condition":"primeiro-rejeitado","text":"Não estou contestando sua gratidão. Estou contestando sua escolha."}],"question":false},{"line":938,"speaker":"Ghork","choice":"Escolhi o trabalho que quero fazer. Nunca prometi entrar nas três guildas, e nem conseguiria cumprir essa promessa.","expression":"neutro","response":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Ofereci um contrato. Alguém ia sair daqui sem ele. Vamos registrar quem assume a responsabilidade pelo trabalho."}],"question":false},{"line":959,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Minha equipe traz o público que mantém este coliseu aberto. Vocês querem treinar na arena que pagamos e chamam de abuso quando pedimos prioridade?"}]},{"line":961,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"raiva","text":"Quando sua prioridade tira o horário já prometido a outra equipe, sim. É exatamente de abuso que estou chamando."},{"speaker":"Borun","condition":"papel:Borun","expression":"raiva","text":"Estou pedindo que cumpra o acordo. Não devíamos ter de implorar por um horário que já era nosso."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Uma descrição da sua popularidade não responde à pergunta. Que regra permite isso?"}]},{"line":963,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Retire o que disse. Aqui, na frente de todos."}]},{"line":965,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"raiva","text":"Não. Você ouviu muito bem."},{"speaker":"Borun","condition":"papel:Borun","expression":"raiva","text":"Não. Não vou pedir desculpas por esperar que cumpram a palavra."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Mantenho a pergunta. Não vejo motivo para retirá-la."}]},{"line":967,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Rask. Cancele os horários de treino dessa guilda. Se não consegue fazer isso, talvez deva ver como seu campeonato se sai sem mim."}]},{"line":971,"body":[{"speaker":"Rask","condition":"","expression":"triste","text":"Estou retirando seus horários de treino. Vocês terão de treinar fora do coliseu. A inscrição no campeonato continua válida... isso não vou retirar."}]},{"line":973,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":975,"speaker":"Ghork","choice":"Você já tinha confirmado esses horários. Agora vai tirar porque ele mandou?","expression":"raiva","response":[{"speaker":"Rask","condition":"","expression":"triste","text":"Sim. Tem todo o direito de dizer que voltei atrás no que prometi. Não foi um erro na agenda."}],"question":false},{"line":976,"speaker":"Ghork","choice":"E ele fica com a arena? Ele ameaça ir embora, e nós perdemos nosso lugar?","expression":"raiva","response":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Minha equipe vai ter o espaço de que precisa. Fizemos o bastante por este coliseu para merecer isso."}],"question":false},{"line":978,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"A gente já tinha organizado os treinos. Agora vai ter de encontrar espaço para tudo outra vez."}]},{"line":980,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"neutro","text":"Vamos abrir espaço na sede. E ninguém vai perder descanso para pagar pela birra dele."},{"speaker":"Borun","condition":"papel:Borun","expression":"neutro","text":"Vamos dividir o trabalho na sede. Prometi acompanhar aqueles treinos e vou acompanhar. Vamos ver o que cabe em cada espaço."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Na escola, então. Vamos avaliar o espaço e adaptar os exercícios. Ainda temos um campeonato para preparar."}]},{"line":995,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vou ajudar no que puder. E, se não der conta de alguma coisa, aviso antes que vire outro problema."}]},{"line":1004,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Esse esteio fica aqui. Se levarmos todos lá para dentro, o que sobra para trazer alguém de volta?"}]},{"line":1006,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Primeiro, aprendam a montar. Um esteio no lugar errado não sustenta grande coisa."}]},{"line":1008,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E tudo isso sai do nosso pagamento? Quanto, mais ou menos?"}]},{"line":1010,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Mais do que a Zagra está pedindo. Vamos pagar pelas inspeções, pelos esteios, por gente pronta para ajudar na saída. Vai sobrar menos para o campeonato."}]},{"line":1012,"body":[{"speaker":"Ghork","condition":"— perguntas, ambas necessárias","text":""}]},{"line":1014,"speaker":"Ghork","choice":"Digamos que alguma coisa dê errado. O que essa reserva permite fazer?","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Parar. Preparar a volta. Ter alguém livre para ajudar, em vez de todo mundo ocupado carregando os feridos. Não nos torna invulneráveis."}],"question":true},{"line":1015,"speaker":"Ghork","choice":"E se a gente sair sem usar nada disso?","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"O material continua custando. O tempo da equipe também. Prefiro que você reclame do custo aqui em cima. Pior seria só descobrir isso lá embaixo."}],"question":true},{"line":1017,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Chegue mais perto. Está vendo esta junção? Confira com a marca e anote o que acontecer no teste. O peso fica comigo."}]},{"line":1021,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Está bem. Fica mais fácil entender a conta quando vejo o que estamos pagando."}]},{"line":1023,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Ótimo. Agora deixe a Zagra mostrar a dela. Você ainda não escolheu."}]},{"line":1032,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Estas cargas vão conosco. A reserva pesada fica aqui em cima. Levantamos um trecho curto e voltamos. Esse é o trabalho que estou propondo."}]},{"line":1034,"body":[{"speaker":"Pirka","condition":"","expression":"feliz","text":"Menos peso, frete mais barato. Só lembrem: onde começa o túnel, termina o caminho da minha carroça."}]},{"line":1036,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E se alguém se machucar depois desse ponto... a gente traz de volta por conta própria?"}]},{"line":1038,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Com menos equipamento para ajudar. Sim. Não vou enfeitar isso. Em troca, sobraria mais do pagamento para os treinos."}]},{"line":1040,"body":[{"speaker":"Ghork","condition":"— perguntas, ambas necessárias","text":""}]},{"line":1042,"speaker":"Ghork","choice":"O que faria você encerrar o trabalho antes de terminar?","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Rocha instável. Perder o caminho. Alguém sem condições de continuar. Se eu não enxergar uma saída, não levo vocês mais para dentro."}],"question":true},{"line":1043,"speaker":"Ghork","choice":"Tem alguma coisa de que você não abre mão para economizar?","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Marcas para encontrar a saída. Um jeito de manter contato. Cargas que cada um consiga carregar. Sem isso, já não é o trabalho que propus."}],"question":true},{"line":1047,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Você e o Darvek já trabalharam na mesma equipe, não foi?"}]},{"line":1049,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Já. Ele leva o suficiente para enfrentar um problema maior. Eu aceito um trabalho menor. Pode acreditar: essa discussão é mais velha que o seu contrato."}]},{"line":1058,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"neutro","text":"Você ouviu os dois planos. Agora escolha um que consiga defender quando a equipe perguntar por quê."},{"speaker":"Borun","condition":"papel:Borun","expression":"neutro","text":"Antes de me contar quem convenceu você, conte o que foi conferir por conta própria."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Uma proposta convincente não basta. Escolha um método que consiga justificar quando tivermos o resultado."}]},{"line":1066,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vamos com o Darvek. Quero essa reserva pronta antes de alguém entrar. Vou ter que me virar com menos para os treinos."}]},{"line":1068,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Está bem. Venha ajudar a testar os esteios."}]},{"line":1070,"body":[{"speaker":"Zagra","condition":"","expression":"raiva","text":"Você ouviu até onde eu iria. Ainda acha que eu arrastaria minha equipe para dentro e torceria para dar certo?"}]},{"line":1072,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1074,"speaker":"Ghork","choice":"Eu ouvi. Mesmo assim, quero mais ajuda preparada se a volta der errado.","expression":"neutro","response":[],"question":false},{"line":1075,"speaker":"Ghork","choice":"Não acho que você abandonaria ninguém. Eu só dormiria melhor sabendo que temos mais recursos à mão.","expression":"neutro","response":[],"question":false},{"line":1077,"body":[{"speaker":"Zagra","condition":"","expression":"raiva","text":"Está bem. Minha equipe sabe fazer esse trabalho. Vamos encontrar alguém disposto a vir conosco."}]},{"line":1081,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vamos com a Zagra. Um levantamento curto, com dinheiro sobrando para os treinos. Se não der para verificar um trecho com o que levamos, deixamos esse trecho para depois."}]},{"line":1083,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Então ponha isso no plano. Quero que todos ouçam a mesma coisa antes de arrumarmos a carga."}]},{"line":1085,"body":[{"speaker":"Darvek","condition":"","expression":"triste","text":"E se a volta exigir mais de vocês do que a ida? A minha reserva ainda vai parecer exagero?"}]},{"line":1087,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1089,"speaker":"Ghork","choice":"Sua reserva cobriria isso. Eu sei. Estou aceitando o risco de ter menos recursos à mão.","expression":"neutro","response":[],"question":false},{"line":1090,"speaker":"Ghork","choice":"Não estou chamando você de covarde, Darvek. Estou dizendo que vamos parar antes.","expression":"neutro","response":[],"question":false},{"line":1092,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Então lembre disso quando faltar só mais uma curva para verificar. Vou encontrar trabalho para minha equipe."}]},{"line":1101,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"As peças estão prontas. Quem vai montar? Quero mostrar as junções a essa pessoa."}]},{"line":1103,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Minha equipe monta. Ghork, confira a lista e o caminho até o ponto de espera. Veja se conseguimos chegar lá com tudo isso."}]},{"line":1105,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Quero ficar para o teste. Fui eu que disse que precisávamos disso."}]},{"line":1107,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Então fique. E pergunte. Não aprove nada por vergonha de dizer que não entendeu minha explicação."}]},{"line":1111,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1113,"speaker":"Ghork","choice":"Digamos que um de nós precise parar. Quem fica com a carga dessa pessoa?","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Boa pergunta. Troquem de lugar, pessoal. Vamos tentar a volta desse jeito."}],"question":false},{"line":1114,"speaker":"Ghork","choice":"Com todo mundo passando por aqui, ainda dá para alcançar os esteios?","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Assim, não. Desobstruam a passagem. Vamos tentar de novo."}],"question":false},{"line":1118,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Agora sim. Aqui está o custo da reserva, separado do material que vamos usar no levantamento."}]},{"line":1120,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Isso dá... um bom número de treinos, empilhados na forma de esteios."}]},{"line":1122,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Dá mesmo. Confira as contas comigo se quiser. Pedi que você abrisse mão disso; não vou esconder o preço."}]},{"line":1133,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Parem aqui. Não gostei daquele suporte. Vamos conferir antes de alguém avançar."}]},{"line":1135,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Já vamos parar? Depois de todo o tempo que passamos preparando a entrada?"}]},{"line":1137,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Foi para isso que nos preparamos. Para poder parar e organizar a saída. Aqueles esteios não mudam a rocha."}]},{"line":1139,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1141,"speaker":"Ghork","choice":"Está bem. Enquanto você verifica, vou anotar o que vimos.","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Marque onde paramos. Deixe o resto em branco; ainda não vimos o que há lá."}],"question":false},{"line":1142,"speaker":"Ghork","choice":"Mostre o que está preocupando você. Se perguntarem por que paramos, quero saber responder.","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Aquele suporte sustenta esta passagem. Minha equipe vai verificar. Anote isso como o motivo da parada."}],"question":false},{"line":1146,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Achei que teríamos mais para mostrar na volta."}]},{"line":1148,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Eu também. Vamos mostrar o que conferimos e explicar por que não avançamos."}]},{"line":1150,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"E quanto custou. Eu escolhi a reserva. Não vou deixar você explicar a conta sozinho."}]},{"line":1159,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"Lista curta. Confiram mesmo assim. O que esquecerem aqui não vai ficar mais perto depois que sairmos."}]},{"line":1161,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Ghork. Antes de carregar, diga onde esse trabalho termina. Não quero que cada um esteja concordando com uma coisa diferente."}]},{"line":1163,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1165,"speaker":"Ghork","choice":"Se um trecho exigir mais equipamento ou gente do que levamos, não entramos nele.","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Isso. Ponha no relatório também. Ninguém vai chamar de serviço incompleto porque resolveu querer mais depois."}],"question":false},{"line":1166,"speaker":"Ghork","choice":"E o dinheiro que vamos guardar não vai ajudar a carregar alguém para fora. Não teremos a reserva do Darvek.","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Certo. Se o trabalho exigir essa reserva, nosso serviço termina ali."}],"question":false},{"line":1170,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E se alguém quiser voltar, mas não quiser ser a pessoa que pede?"}]},{"line":1172,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Vou perguntar antes de avançar. Você também pode perguntar. E, se for eu quem estiver apressando os outros, espero que me interrompa."}]},{"line":1174,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Isso eu consigo. Prefiro uma conversa desconfortável aqui a descobrir lá embaixo que ninguém queria ir."}]},{"line":1185,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Este é o nosso limite. Não trouxemos o suficiente para passar daqui."}]},{"line":1187,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Mas o trecho que viemos examinar ainda está mais à frente."}]},{"line":1189,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Eu sei. E, se alguém se machucar lá dentro, teremos pouca coisa para ajudar na volta. Foi aqui que eu disse que pararíamos."}]},{"line":1191,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1193,"speaker":"Ghork","choice":"Então vou marcar este ponto. Pelo menos vão saber até onde chegamos.","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"E por quê. Não marque o próximo trecho como intransponível. Não sabemos disso; não fomos conferir."}],"question":false},{"line":1194,"speaker":"Ghork","choice":"Na entrega, eu explico por que voltamos.","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Nós explicamos. Eu propus esse plano, Ghork. Você não precisa responder por ele sozinho."}],"question":false},{"line":1198,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Então continuo com o dinheiro dos treinos. E continuo sem poder dizer o que tem lá embaixo."}]},{"line":1200,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Foi o que aconteceu. Ponha as duas coisas no relatório, mesmo que não seja o final que queríamos."}]},{"line":1202,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Seja lá o que dissermos, não quero que o Darvek vire piada."}]},{"line":1204,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Não vai virar, se depender de mim. A reserva dele teria ajudado aqui. Também teríamos pago por ela."}]},{"line":1215,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Primeiro, mostrem por onde passaram. Depois, onde tiveram que parar."}]},{"line":1217,"body":[{"speaker":"Ghork","condition":", X","expression":"neutro","text":"Montamos a reserva. Quando foi preciso verificar um suporte, paramos e usamos a reserva para organizar a saída. Sobrou menos do pagamento para os treinos."}]},{"line":1219,"body":[{"speaker":"Ghork","condition":", Y","expression":"neutro","text":"Levamos menos equipamento. Quando chegamos ao terreno instável, voltamos. Sobrou mais dinheiro, mas depois desta marca? Não conseguimos verificar."}]},{"line":1221,"body":[{"speaker":"Elune","condition":"","expression":"neutro","text":"Vou colocar cada observação aqui, onde vocês a fizeram. O espaço em branco fica em branco. Não quero que a próxima equipe entenda isso como caminho livre."}]},{"line":1223,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Isso explica o serviço feito. Não libera o restante da mina para exploração. O pagamento combinado vai para a guilda; a divisão segue o acordo de vocês."}]},{"line":1225,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1227,"speaker":"Ghork","choice":"Quero incluir o custo do plano também. Isso pesou na nossa escolha.","expression":"neutro","response":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Inclua. Se contratarmos outro levantamento, vou precisar saber quanto este exigiu."}],"question":false},{"line":1228,"speaker":"Ghork","choice":"Podemos explicar melhor a parada? Não quero que pareça que só nos cansamos do serviço.","expression":"neutro","response":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Descreva o que fez vocês pararem. Seja específico, mas não diga à próxima equipe o que ela vai encontrar. As condições podem mudar."}],"question":false},{"line":1230,"body":[{"speaker":"Darvek","condition":"papel:Darvek","expression":"neutro","text":"A reserva permitiu reorganizar a equipe para a volta. Aqui estão as despesas, uma por uma."},{"speaker":"Zagra","condition":"papel:Zagra","expression":"neutro","text":"Nosso plano terminava ali. Respeitamos isso. Receber o pagamento não nos dá uma resposta sobre o resto."}]},{"line":1238,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Duas peças prontas! Duas! Vou começar a mostrar para as pessoas. Ver se alguém quer comprar alguma coisa."}]},{"line":1240,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Duas? Quando você achou tempo para tudo isso?"}]},{"line":1242,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"O quê, era para esperar a loja aparecer? Preciso de clientes antes de precisar de um balcão."}]},{"line":1244,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1246,"speaker":"Ghork","choice":"Vamos, mostre. Quero ver o que você fez.","expression":"feliz","response":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Esta é minha preferida. Aquela deu mais trabalho. Não pergunte pela manga. Eu e a manga ainda estamos discutindo."}],"question":false},{"line":1247,"speaker":"Ghork","choice":"Eu estava falando sério sobre a loja. Ainda quero ajudar você a chegar lá.","expression":"neutro","response":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Eu sei. Mas olhe esta parte primeiro. Aqui, a manga. Fui eu que fiz, Ghork."}],"question":false},{"line":1249,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Estou olhando. Ficou boa. Também tenho uma coisa para contar... terminei um trabalho nas minas."}]},{"line":1251,"body":[{"speaker":"Lala","condition":"","expression":"confuso","text":"Nas minas? Ah, você vai me contar tudo. Mas, primeiro, o Dam mandou um recado. Escute antes de prometer uma casa inteira."}]},{"line":1253,"body":[{"speaker":"Lala","condition":", lendo o recado de Dam","expression":"neutro","text":"“Apareceu uma goteira no quarto coletivo. Estou organizando o conserto, mas falta material. Você consegue ajudar com alguma coisa agora? Preciso saber o que mais vou ter que arranjar.”"}]},{"line":1255,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Estou com a minha parte do pagamento. Ia usar para treinar mais..."}]},{"line":1257,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Ele precisa saber, seja qual for a resposta. Diga o que você consegue fazer e eu passo o recado."}]},{"line":1263,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Consigo mandar uma parte para o material. Diga isso a ele. A casa inteira vai demorar um pouco mais."}]},{"line":1265,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Vou dizer. Ele vai perguntar quando chega. O que respondo?"}]},{"line":1267,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Que vou combinar a entrega primeiro. Não quero deixar ele esperando por uma data que inventei."}]},{"line":1271,"body":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"Confira aqui a quantia e o nome de quem recebe. A Pirka leva na saída que combinamos. Esta cópia fica comigo."}]},{"line":1273,"body":[{"speaker":"Pirka","condition":"","expression":"neutro","text":"É isso que vou levar. Se a saída mudar, eu aviso. Enquanto eu não entregar, não diga a eles que já chegou."}]},{"line":1275,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Entendi. Posso ficar com uma cópia? Quero passar os dados certos para o Dam."}]},{"line":1279,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Desta vez, preciso guardar para os treinos. Diga a ele... diga que não consigo mandar nada agora."}]},{"line":1281,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Está bem. Talvez ele fique decepcionado. Prefiro dar a sua resposta a deixar ele esperando."}]},{"line":1283,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Achei que a esta altura já teria mais para mandar para ele."}]},{"line":1285,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Vou dar o recado a ele. Mas, da próxima vez, conte como você está também, está bem?"}]},{"line":1289,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"E você tem que me contar quando vender essas peças. Quero saber disso."}]},{"line":1291,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Vou contar vendendo ou não. Você não vai escapar da história da manga."}]},{"line":1299,"body":[{"speaker":"Dorga","condition":"","expression":"raiva","text":"Quando ninguém queria pagar por aquelas expedições, nossa guilda pagou. Agora os contratos vão para gente que nem estava lá."}]},{"line":1301,"body":[{"speaker":"Meruna","condition":"","expression":"neutro","text":"Eu não esqueci. Mas estou avaliando o trabalho proposto agora. Preciso dos detalhes, seja quem for que traga a proposta."}]},{"line":1303,"body":[{"speaker":"Dorga","condition":"","expression":"raiva","text":"E as famílias dos nossos veteranos? Ainda estão aqui, Meruna. Você pode mudar os critérios. Não pode esperar que elas deixem de precisar de trabalho."}]},{"line":1307,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1309,"speaker":"Ghork","choice":"Sua mão... você está bem?","expression":"confuso","response":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"São os anos de arena. Uma hora eles pesam. Meu fornecedor está cuidando disso."}],"question":false},{"line":1310,"speaker":"Ghork","choice":"Então, pronto para as eliminatórias?","expression":"neutro","response":[{"speaker":"Torvak","condition":"","expression":"feliz","text":"Estou pronto para quem achar que chegou sua vez de tomar meu lugar."}],"question":false},{"line":1312,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"O treinamento dele exige muito do corpo. Interromper as doses sem acompanhamento só agravaria a situação."}]},{"line":1314,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Já que estamos falando de treino... foi você que fez o Rask cancelar os nossos."}]},{"line":1316,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Fui eu. Seu mentor poderia ter retirado aquela acusação. Minha equipe não vai abrir espaço toda vez que alguém decidir que não merecemos o que conquistamos."}]},{"line":1318,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1320,"speaker":"Ghork","choice":"Então diga isso com todas as letras. Não venha chamar de erro de agenda depois.","expression":"raiva","response":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Acabei de dizer. Pronto. Agora tente me vencer na arena."}],"question":false},{"line":1321,"speaker":"Ghork","choice":"É fácil chamar de conquista quando quem abre mão de alguma coisa são os outros.","expression":"raiva","response":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Acha que fiquei neste lugar por tantos anos sem pagar um preço? Volte quando tiver feito tanto quanto eu."}],"question":false},{"line":1329,"body":[{"speaker":"Guedra","condition":", se contribuiu","expression":"neutro","text":"Não temos o treino extra, mas ainda temos nosso horário marcado. Vamos aproveitar. Mostre onde você perde o apoio."}]},{"line":1331,"body":[{"speaker":"Guedra","condition":", se guardou","expression":"neutro","text":"Com esse treino extra, dá para dedicar mais tempo à sua base. Nisso, consigo ajudar. Ganhar já é outra história."}]},{"line":1333,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Vamos começar pela parte em que tento fazer a perna ficar mais comprida porque meus braços não alcançam."}]},{"line":1335,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Então vamos pegar esse momento. Devagar, para eu enxergar."}]},{"line":1339,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Sua equipe está classificada. Ainda dá tempo de convidar pessoas antes do mata-mata. Confirme a inscrição quando estiver pronto; depois disso, a equipe fica fechada."}]},{"line":1341,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Ali. É o meu nome?"}]},{"line":1343,"body":[{"speaker":"Rask","condition":"","expression":"feliz","text":"É seu. Pode ler de novo, se quiser."}]},{"line":1351,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1353,"speaker":"Ghork","choice":"Você me ajudou a chegar aqui. Não esqueci disso. Mas, daqui para a frente, quero fazer minhas próprias escolhas.","expression":"neutro","response":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"neutro","text":"Está bem. Conte o que está pensando. Vou tentar não responder por você antes que termine."},{"speaker":"Borun","condition":"papel:Borun","expression":"feliz","text":"Ótimo. Eu ficaria decepcionado se você não fizesse isso."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Então esteja pronto para explicar essas escolhas quando alguém questionar."}],"question":false},{"line":1354,"speaker":"Ghork","choice":"Posso aproveitar meu nome ali antes de chegarmos à próxima lista do que devo fazer por todo mundo?","expression":"feliz","response":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"feliz","text":"Pode. Tem razão. Hoje, vamos comemorar."},{"speaker":"Borun","condition":"papel:Borun","expression":"feliz","text":"Ah, minha lista está tão comprida assim? Então é melhor começar a reclamar agora."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"feliz","text":"Muito bem. Comemore. Vou guardar minhas cobranças até você pelo menos terminar esta conversa."}],"question":false},{"line":1356,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Então se classificou, Ghork. Seu mentor conseguiu onde treinar depois de toda aquela confusão."}]},{"line":1358,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Conseguimos. Teria sido mais fácil sem você nos obrigar a refazer tudo."}]},{"line":1360,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Então vamos ver o que conseguiram fazer."}]},{"line":1397,"body":[{"speaker":"Nyra","condition":"","expression":"neutro","text":"Sobrou um horário à noite no pátio e tenho duas pessoas querendo usar. Ghork, dê uma olhada com elas. Antes de abrir, quero saber quem vai cuidar do lugar."}]},{"line":1399,"body":[{"speaker":"Brakka","condition":"","expression":"neutro","text":"Treino depois do trabalho. É isso que estou pedindo. Tem gente ainda no serviço quando as aulas começam. Nunca consegue participar."}]},{"line":1401,"body":[{"speaker":"Nima","condition":"","expression":"neutro","text":"E eu preciso de um lugar para despachar as entregas noturnas. Saímos juntos, conferimos quem voltou. Sem uma base, cada um acaba andando sozinho por essas ruas."}]},{"line":1403,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Um de vocês não podia começar depois? Dividir a noite?"}]},{"line":1405,"body":[{"speaker":"Nyra","condition":"","expression":"neutro","text":"Se conseguir fazer as caixas atravessarem as pessoas. É um horário, Ghork. Não tenho quem cuide do pátio em outro momento."}]},{"line":1409,"body":[{"speaker":"Nima","condition":"","expression":"neutro","text":"As cargas passam por aqui. Bloqueie isso e nada entra nem sai."}]},{"line":1411,"body":[{"speaker":"Brakka","condition":"","expression":"neutro","text":"Posso pôr os bancos aqui. A menos que fique tudo cheio de caixas, claro. Aí terei uma turma sem espaço nem para ficar em pé."}]},{"line":1413,"body":[{"speaker":"Ghork","condition":"","text":"Entendi. Não vou prometer o mesmo pátio duas vezes."}]},{"line":1423,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vamos abrir espaço para os treinos do Brakka. Eu ajudo a preparar."}]},{"line":1425,"body":[{"speaker":"Nima","condition":"","expression":"triste","text":"Então preciso de outro lugar para as entregas. Achei que finalmente fôssemos resolver isso."}]},{"line":1427,"body":[{"speaker":"Brakka","condition":"","expression":"feliz","text":"Certo! Primeiro, os bancos. Ghork, confira esta lista, veja quem consegue vir. Talvez eu tenha me animado antes de receber todas as respostas."}]},{"line":1431,"body":[{"speaker":"Nyra","condition":"","expression":"neutro","text":"A lista está certa. Quem guardar o material tranca o pátio. Não quero que deixem isso para mim."}]},{"line":1433,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Combinamos cuidar do lugar. Isso inclui a fechadura."}]},{"line":1437,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vamos dar uma base às entregas da Nima. Eu ajudo com as caixas."}]},{"line":1439,"body":[{"speaker":"Brakka","condition":"","expression":"triste","text":"Está bem. Vou continuar procurando. Aquelas pessoas ainda precisam de onde treinar, mesmo que não seja aqui."}]},{"line":1441,"body":[{"speaker":"Nima","condition":"","expression":"neutro","text":"Ótimo. Aqui estão as etiquetas. Confira as caixas comigo, depois os retornos. O que ninguém reconhecer fica de lado. Nada de adivinhar."}]},{"line":1445,"body":[{"speaker":"Nyra","condition":"","expression":"neutro","text":"Está bem. Mantenham a passagem livre até a última pessoa voltar. Não só até cansarem de prestar atenção nela."}]},{"line":1447,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Nada de banco no caminho. Pode acreditar: aprendi o estrago que um banco faz quando você precisa sair depressa."}]},{"line":1464,"body":[{"speaker":"Ghork","condition":"","text":"Entendi. Espero ver o que conseguiram."}]},{"line":1473,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"Continuo atendendo gente que se machucou naquele pátio. Quero que isso pare. Podemos usar os registros de atendimento para mostrar o que acontece sem expor os pacientes."}]},{"line":1475,"body":[{"speaker":"Edrin","condition":"","expression":"neutro","text":"Algumas dessas pessoas querem falar em público, com nome. Eu reuniria quem quiser depor e cobraria uma resposta dos responsáveis."}]},{"line":1477,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Vocês dois querem impedir que mais gente se machuque. O que impede vocês de fazer isso juntos?"}]},{"line":1479,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"O que acontece com essas pessoas depois. É aí que discordamos. Antes de escolher, ouça alguém que se machucou."}]},{"line":1481,"body":[{"speaker":"Ferido","condition":"","expression":"triste","text":"Podem usar o que eu contar. Só... sem nome. Ainda preciso que aquela gente me contrate. Não posso deixar que me reconheçam nisso."}]},{"line":1483,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1485,"speaker":"Ghork","choice":"Está bem. Seu nome fica de fora.","expression":"neutro","response":[{"speaker":"Ferido","condition":"","expression":"neutro","text":"Então... pergunte sobre o equipamento. Disso eu posso falar."}],"question":false},{"line":1486,"speaker":"Ghork","choice":"Diga o que você se sente à vontade para deixar a gente contar.","expression":"neutro","response":[{"speaker":"Ferido","condition":"","expression":"neutro","text":"O que aconteceu comigo. Meu nome, não. Nem onde trabalho."}],"question":false},{"line":1488,"body":[{"speaker":"Ferido","condition":"","expression":"triste","text":"O suporte cedeu no meio do exercício. Disseram que eu era desastrado. Quem me ajudou guardou um pedaço e levou para a Guedra. Pelo menos alguém quis olhar aquilo."}]},{"line":1490,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"A Guedra vai nos emprestar a peça. Leve esta autorização e traga o pedaço. Vamos ver o que ele pode nos dizer antes de decidir de quem é a culpa."}]},{"line":1496,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Trouxeram isso para mim depois. Não vi quebrar, Ghork. Eu dou aula aqui; o acidente foi em outro pátio."}]},{"line":1498,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Entendi. Precisamos que alguém examine o dano, não que complete a história que ninguém viu."}]},{"line":1500,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Leve ao Durn. Ele pode fazer isso. E traga de volta depois. Precisamos guardar essa peça."}]},{"line":1504,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Está vendo aqui? Há uma falha. Isso eu consigo mostrar. Quem montou, quem percebeu o desgaste antes de quebrar... a peça não me conta isso."}]},{"line":1506,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1508,"speaker":"Ghork","choice":"Anote isso também. Não quero que seu laudo diga mais do que você pode afirmar.","expression":"neutro","response":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Não vai dizer. Vou descrever o que encontrei. Para acusar alguém, vocês vão precisar de mais do que isso."}],"question":false},{"line":1509,"speaker":"Ghork","choice":"Deixe as pessoas envolvidas lerem antes de levarmos isso adiante. Elas precisam saber o que estamos associando ao relato delas.","expression":"neutro","response":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Leve uma cópia. Se encontrarem alguma coisa errada, tragam para mim. Prefiro corrigir agora."}],"question":false},{"line":1513,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Vou guardar a peça aqui, junto com o registro de quem examinou. Podemos precisar dela de novo."}]},{"line":1515,"body":[{"speaker":"Edrin","condition":", na enfermaria","expression":"neutro","text":"Isso basta para pedir uma investigação. Não para dizer que alguém quis que acontecesse."}]},{"line":1517,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"Deixe eu conferir a cópia mais uma vez. Tirar o nome não protege ninguém se os detalhes entregarem a pessoa."}]},{"line":1521,"body":[{"speaker":"Edrin","condition":"","expression":"neutro","text":"Vou reunir quem quer depor. Só essas pessoas. Quem pediu sigilo fica fora da lista de nomes."}]},{"line":1523,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"E eu posso apresentar os ferimentos e as conclusões do Durn sem identificar os pacientes. Ghork, qual apresentação você vai ajudar a preparar? Não dá tempo de fazer as duas."}]},{"line":1529,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Aqui estão os relatos que recolhemos e as conclusões sobre a peça quebrada. Os pacientes permitiram que usássemos suas histórias. Não que revelássemos seus nomes."}]},{"line":1531,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"Por favor, investigue o equipamento e as condições daquele pátio. Isto é o que conseguimos apurar. Não queremos esperar alguém se machucar de novo."}]},{"line":1533,"body":[{"speaker":"Seldan","condition":"","expression":"neutro","text":"Vou receber o material e registrar o pedido. Apontar um responsável vem depois da investigação, não antes."}]},{"line":1535,"body":[{"speaker":"Edrin","condition":"","expression":"neutro","text":"Vou continuar procurando quem queira depor. Isso não muda o que prometemos aos pacientes deste relatório."}]},{"line":1539,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Todos aqui escolheram falar. Mantivemos o relato sigiloso separado. Aquele paciente não faz parte destes depoimentos."}]},{"line":1541,"body":[{"speaker":"Edrin","condition":"","expression":"neutro","text":"Antes de confirmar qualquer coisa, releiam seus depoimentos. Corrijam o que precisar. Já temos o exame da peça; de vocês, precisamos do que viram."}]},{"line":1543,"body":[{"speaker":"Testemunha","condition":"figurante","expression":"confuso","text":"Esta parte está errada. A ordem. Aconteceu depois que mudaram o exercício, não antes."}]},{"line":1545,"body":[{"speaker":"Edrin","condition":"","expression":"neutro","text":"Depois da mudança. Pronto, corrigido. O resto está como você lembra?"}]},{"line":1547,"body":[{"speaker":"Testemunha","condition":"","expression":"neutro","text":"Sim. Está certo."}]},{"line":1549,"body":[{"speaker":"Seldan","condition":"","expression":"neutro","text":"Vou receber os depoimentos e o pedido. Também precisamos ouvir os responsáveis pelo pátio antes de chegar a uma conclusão."}]},{"line":1551,"body":[{"speaker":"Sura","condition":"","expression":"neutro","text":"Vou continuar atendendo quem precisar de mim. E, por favor, lembrem: uma audiência pública não desfaz uma promessa de sigilo."}]},{"line":1557,"body":[{"speaker":"Ghork","condition":"","text":"Quero que entre na minha equipe para o campeonato."}]},{"line":1571,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Vou doar esta estrutura para um projeto. Korr quer as peças; Velka quer ela inteira. Ninguém pega ferramenta até decidirmos."}]},{"line":1573,"body":[{"speaker":"Korr","condition":"","expression":"feliz","text":"Olhe esse material! Dá para fazer proteção que as pessoas consigam pagar. Não para Terminus inteira, antes que alguém pergunte. Mas alguns conjuntos."}]},{"line":1575,"body":[{"speaker":"Velka","condition":"","expression":"neutro","text":"E eu posso ensinar com ela assim. Deixem eu mostrar o movimento. Depois de desmontada, perdemos onde praticar."}]},{"line":1577,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Quero ver. Não quero escolher só pelas duas descrições do mesmo monte de metal."}]},{"line":1581,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Deem espaço para ela. Mantenham a passagem livre. Velka, mostre a transferência de peso."}]},{"line":1583,"body":[{"speaker":"Velka","condition":"","expression":"neutro","text":"Aqui. Viu quanto espaço preciso entre os apoios? Por enquanto, só olhe, Ghork. Não preciso que você force a perna para provar meu argumento."}]},{"line":1585,"body":[{"speaker":"Korr","condition":"","expression":"neutro","text":"Ah. Sim, agora entendi. Mas são justamente as peças que eu usaria. Não consigo tirar sem acabar com esse movimento."}]},{"line":1587,"body":[{"speaker":"Ghork","condition":"— perguntas livres","text":""}]},{"line":1589,"speaker":"Ghork","choice":"Korr, explique melhor. O que daria para fazer com isso?","expression":"neutro","response":[{"speaker":"Korr","condition":"","expression":"feliz","text":"Alguns conjuntos de proteção. Testados antes de alguém vestir, claro. Pense em quem está se virando como pode porque equipamento novo custa caro demais."}],"question":true},{"line":1590,"speaker":"Ghork","choice":"Velka, se mantivermos a estrutura, quem vai poder usar?","expression":"neutro","response":[{"speaker":"Velka","condition":"","expression":"neutro","text":"Quem vier às aulas que eu organizar. E eu vou ensinar. Não pediria para você preservar isso só para eu admirar a estrutura parada aqui."}],"question":true},{"line":1598,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vou apoiar as proteções. Korr, vamos conferir o que temos antes de soltar qualquer peça."}]},{"line":1600,"body":[{"speaker":"Velka","condition":"","expression":"triste","text":"Eu queria manter a estrutura. Vou procurar outro jeito de ensinar o movimento, mas... não, não consigo substituir isso amanhã."}]},{"line":1602,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Está bem. Korr desmonta. Ghork, anote cada peça que sair. Não vamos perder nada pelo chão."}]},{"line":1604,"body":[{"speaker":"Korr","condition":"","expression":"neutro","text":"O primeiro conjunto vai ser testado antes de ser usado. E leva meu nome. Se der problema, quero que venham falar comigo."}]},{"line":1608,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"A estrutura fica inteira. Velka, vou ajudar você a começar as aulas."}]},{"line":1610,"body":[{"speaker":"Korr","condition":"","expression":"triste","text":"Vou encontrar outro material. Só... usem, está bem? Depois disso tudo, não quero ver a estrutura aqui juntando poeira."}]},{"line":1612,"body":[{"speaker":"Velka","condition":"","expression":"neutro","text":"Nem eu. Vou falar com a Guedra e marcar a primeira aula."}]},{"line":1614,"body":[{"speaker":"Durn","condition":"","expression":"neutro","text":"Então fica para as aulas. Vou registrar a entrega. Uma estrutura, ainda inteira."}]},{"line":1618,"body":[{"speaker":"Ghork","condition":"","text":"Quer levar esse trabalho comigo para o campeonato?"}]},{"line":1632,"body":[{"speaker":"Tessa","condition":"","expression":"raiva","text":"Estamos quase terminando a cisterna e a equipe ainda não recebeu. Queremos o pagamento antes da entrega. Depois que a chave sair da nossa mão, o que sobra para negociar?"}]},{"line":1634,"body":[{"speaker":"Mavren","condition":"","expression":"neutro","text":"Propus deixar o dinheiro com Jorvi para liberar na entrega. Mas precisamos conferir a quantia e as condições. Não estou pedindo que ninguém aceite só na confiança."}]},{"line":1636,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"O dinheiro já está com Jorvi? Ou ainda estamos falando de uma promessa?"}]},{"line":1638,"body":[{"speaker":"Mavren","condition":"","expression":"neutro","text":"Vamos descobrir. Até lá, a chave fica aqui. Alguém dizer que pagou não basta."}]},{"line":1640,"body":[{"speaker":"Tessa","condition":"","expression":"neutro","text":"E, antes de voltar com a resposta pronta, ouça quem está esperando pelo salário."}]},{"line":1648,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vou comparar o que devem com o depósito e trazer a resposta. Assim vocês vão saber o que estão pedindo que aceitem."}]},{"line":1654,"body":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"O dinheiro está aqui. Esta é a sua cópia do registro. Confira com cada pagamento devido."}]},{"line":1656,"body":[{"speaker":"Ghork","condition":"— investigação, ambas necessárias","text":""}]},{"line":1658,"speaker":"Ghork","choice":"O cliente pode retirar o dinheiro antes de entregarmos a cisterna?","expression":"neutro","response":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"Não. Pelo acordo que aceitei, está reservado para estes pagamentos. O cliente não pode simplesmente retirar."}],"question":true},{"line":1659,"speaker":"Ghork","choice":"E quem precisa confirmar que a entrega foi concluída?","expression":"neutro","response":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"Quem recebe e os representantes dos trabalhadores. Preciso da confirmação dos dois lados antes de liberar qualquer quantia."}],"question":true},{"line":1661,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"E se os trabalhadores lerem isso e ainda assim não aceitarem?"}]},{"line":1663,"body":[{"speaker":"Jorvi","condition":"","expression":"neutro","text":"Então não entregue a chave dizendo que concordaram. Leve a cópia. Deixe que leiam por conta própria."}]},{"line":1669,"body":[{"speaker":"Mavren","condition":"","expression":"neutro","text":"Conferi a lista. Está tudo lá, o suficiente para cobrir a dívida. Nessas condições, estou disposto a terminar e entregar."}]},{"line":1671,"body":[{"speaker":"Tessa","condition":"","expression":"neutro","text":"É melhor do que uma promessa, sim. Ainda quero os salários pagos primeiro. Podemos exigir isso enquanto a cisterna estiver nas nossas mãos."}]},{"line":1673,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1675,"speaker":"Ghork","choice":"Vou respaldar a suspensão até quitarem.","response":[],"question":false},{"line":1676,"speaker":"Ghork","choice":"Vou ajudar a concluir com essa garantia verificada.","response":[],"question":false},{"line":1677,"speaker":"Ghork","choice":"Preciso pensar antes de assumir uma das posições.","response":[],"question":false},{"line":1683,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Conferimos o depósito. Ele existe. Mesmo assim, apoio esperar o pagamento da equipe antes de entregar a chave."}]},{"line":1685,"body":[{"speaker":"Tessa","condition":"","expression":"neutro","text":"Vou anotar quem apoia essa decisão comigo. Quem não apoiar, pode dizer. Não vou falar por vocês."}]},{"line":1687,"body":[{"speaker":"Mavren","condition":"","expression":"triste","text":"Não concordo. Não vou tirar a chave das mãos de vocês, mas não posso passar essa espera sem trabalho. Vou ter que procurar."}]},{"line":1691,"body":[{"speaker":"Tessa","condition":"","expression":"neutro","text":"Ainda não recebemos, Ghork. Isso não acaba porque concordamos. Amanhã, vamos ter que negociar de novo."}]},{"line":1693,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu sei. Vou manter o que disse. E não vou dizer ao Mavren que essa espera não custa nada a ele."}]},{"line":1697,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Vou ajudar a terminar. Conferimos o dinheiro, e os representantes precisam confirmar a entrega antes da liberação."}]},{"line":1699,"body":[{"speaker":"Tessa","condition":"","expression":"neutro","text":"O dinheiro está garantido. Reconheço isso. Ainda preferia receber primeiro. Quem quiser aceitar esse acordo pode falar por si."}]},{"line":1703,"body":[{"speaker":"Mavren","condition":"","expression":"neutro","text":"A chave foi entregue. O pagamento está autorizado. Antes de alguém ir embora, confira se está com sua cópia."}]},{"line":1705,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Depois de carregar tanto papel, eu ficaria preocupado se isso terminasse num “confia em mim” e um aperto de mão."}]},{"line":1711,"body":[{"speaker":"Ghork","condition":"","text":"Quero que entre na minha equipe. Podemos representar esse compromisso no campeonato."}]},{"line":1723,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Tenho um horário de exibição antes do mata-mata. Duas propostas para ele. Por favor, não me peçam para encaixar as duas."}]},{"line":1725,"body":[{"speaker":"Odrik","condition":"","expression":"feliz","text":"Um espetáculo para arrecadar para a enfermaria. Consiga um público e eu dou a ele um motivo para abrir a bolsa. Os pacientes não vão precisar ficar lá sendo olhados."}]},{"line":1727,"body":[{"speaker":"Lethra","condition":"","expression":"neutro","text":"Quero que os aprendizes mostrem seu trabalho. Com seus próprios nomes. Quando há um lutador famoso na frente, as pessoas esquecem de olhar para o resto."}]},{"line":1729,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"E onde eu entro? Além de ser quem tem que escolher."}]},{"line":1731,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Ajude a preparar a apresentação que escolher e traga o programa. Preciso saber o que vou anunciar antes de subir lá."}]},{"line":1737,"body":[{"speaker":"Odrik","condition":"","expression":"feliz","text":"Imagine: “Ghork, o terror que...” Não? Seu rosto está dizendo um não bem firme."}]},{"line":1739,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1741,"speaker":"Ghork","choice":"Meu nome já me dá problema suficiente sem a sua ajuda.","expression":"feliz","response":[{"speaker":"Odrik","condition":"","expression":"feliz","text":"Só Ghork, então. Guardo o terror para quando você perder a hora da minha entrada."}],"question":false},{"line":1742,"speaker":"Ghork","choice":"Conte sobre a luta. Minha história, deixe comigo.","expression":"neutro","response":[{"speaker":"Odrik","condition":"","expression":"neutro","text":"Justo. Temos uma apresentação que vale assistir. Posso atrair o público com isso."}],"question":false},{"line":1746,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Odrik e seus parceiros se apresentam em apoio à enfermaria! As contribuições serão recolhidas pelos organizadores, que prestarão contas do valor arrecadado."}]},{"line":1750,"body":[{"speaker":"Odrik","condition":"","expression":"feliz","text":"Público, dinheiro para a enfermaria e ninguém virando piada. Nada mal, hein? Gostei, Ghork. De trabalhar com você."}]},{"line":1752,"body":[{"speaker":"Lethra","condition":"","expression":"triste","text":"Vou encontrar outro lugar para os aprendizes. Queria que tivessem um público sem precisar pegar a fama de alguém emprestada."}]},{"line":1756,"body":[{"speaker":"Lethra","condition":"","expression":"neutro","text":"Leia como se estivesse anunciando, Ghork. Todos os nomes. Quero saber quanto tempo leva antes de começarmos os movimentos."}]},{"line":1758,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Dá tempo de falar todos. Mas você teria dado o primeiro golpe enquanto eu ainda estivesse lendo."}]},{"line":1760,"body":[{"speaker":"Lethra","condition":"","expression":"neutro","text":"Então o primeiro golpe pode esperar. Deixe o público ouvir quem vai assistir."}]},{"line":1764,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"A seguir, uma demonstração dos aprendizes de Lethra! Cada participante será apresentado antes do início do exercício."}]},{"line":1768,"body":[{"speaker":"Lethra","condition":"","expression":"feliz","text":"Ouviram os nomes dos alunos antes de procurar por mim. Era isso que eu queria. Obrigada por conferir o programa."}]},{"line":1770,"body":[{"speaker":"Odrik","condition":"","expression":"neutro","text":"Vou procurar outra equipe para o espetáculo. Se precisarem de ajuda com uma entrada, sabem onde me achar. E sim, eu queria esse horário. Posso ficar decepcionado."}]},{"line":1774,"body":[{"speaker":"Ghork","condition":"","text":"Ainda tenho uma vaga na equipe para você. Quer disputar comigo?"}]},{"line":1790,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Última conferência antes de entrar. Depois que confirmar a equipe, os convites se encerram. Se ainda quer procurar alguém, é agora."}]},{"line":1794,"body":[{"speaker":"Ghork","condition":", zero recrutados","expression":"neutro","text":"Vou entrar sozinho."}]},{"line":1796,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Sua inscrição permite. Confirme quando estiver pronto para enfrentá-los."}]},{"line":1798,"body":[{"speaker":"Ghork","condition":", com aliados","expression":"feliz","text":"Esta é a minha equipe. Estamos prontos."}]},{"line":1800,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Confirmado. Aguarde a chamada para a primeira partida."}]},{"line":1812,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Minha equipe veio para vencer. Ainda temos pacientes para atender, e aquele contrato teria ajudado a pagar o trabalho."}]},{"line":1814,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu não esqueci."}]},{"line":1816,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Que bom. Então entende por que não vou pedir que abram caminho para você."}]},{"line":1818,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1820,"speaker":"Ghork","choice":"Nem pediria. Você me ajudou, mas eles também vieram disputar esta luta.","expression":"neutro","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Então não temos mais nada para acertar antes da partida."}],"question":false},{"line":1821,"speaker":"Ghork","choice":"Quero ganhar deles numa luta de verdade.","expression":"feliz","response":[{"speaker":"Virmura","condition":"","expression":"feliz","text":"Ainda bem. Foi para isso que eles vieram."}],"question":false},{"line":1823,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Equipe de Ghork contra a guilda de Virmura! Aos lugares."}]},{"line":1825,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Vocês venceram. Agora, alguém precisa de atendimento? Vamos cuidar das duas equipes."}]},{"line":1827,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Obrigado. Diga a eles que deram trabalho."}]},{"line":1829,"body":[{"speaker":"Virmura","condition":"","text":"“Volte quando estiver em condição. Minha equipe também vai se preparar.”"}]},{"line":1833,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Arranjamos outro serviço para manter o pessoal. Eu queria aquele contrato, claro. Mas não dava para ficar sentado esperando você mudar de ideia."}]},{"line":1835,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1837,"speaker":"Ghork","choice":"Que bom que vocês se acertaram. Mas ainda quero ganhar de vocês.","expression":"feliz","response":[{"speaker":"Borun","condition":"","expression":"feliz","text":"Pode tentar. Eles vão dar trabalho."}],"question":false},{"line":1838,"speaker":"Ghork","choice":"Você já me deu bastante conselho. Hoje eu não vou pedir nenhum.","expression":"feliz","response":[{"speaker":"Borun","condition":"","expression":"feliz","text":"Ainda bem. Hoje os conselhos são para eles."}],"question":false},{"line":1840,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Equipe de Ghork contra a guilda de Borun! Lutadores, preparem-se."}]},{"line":1842,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Você leu bem a luta. Só não me peça para comemorar."}]},{"line":1844,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Nem ia pedir. Eu comemoro o suficiente por nós dois."}]},{"line":1846,"body":[{"speaker":"Borun","condition":"","text":"“Eles também aprenderam a observar. Se voltar, encontrará gente prestando atenção em você.” Não entrega dica secreta que traia sua equipe."}]},{"line":1850,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Minha escola não parou quando você escolheu outra guilda. Meus representantes querem mostrar o que aprenderam."}]},{"line":1852,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1854,"speaker":"Ghork","choice":"Estou curioso para ver o que prepararam para a arena.","expression":"feliz","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Vai poder conferir de perto."}],"question":false},{"line":1855,"speaker":"Ghork","choice":"Eles são bons. Posso reconhecer isso e continuar satisfeito com minha escolha.","expression":"neutro","response":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Veremos se diz o mesmo depois da partida."}],"question":false},{"line":1857,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Equipe de Ghork contra a escola de Sevrak! Lutadores, aos lugares."}]},{"line":1859,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Você lutou bem. A vitória é sua. Isso não mudou minha opinião sobre o contrato."}]},{"line":1861,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Não esperava que mudasse. E não estou pedindo para me aceitar de volta."}]},{"line":1863,"body":[{"speaker":"Sevrak","condition":"","text":"“Minha equipe soube usar o que preparou. A próxima tentativa exigirá mais atenção.” Ghork pode preparar-se sem receber treino exclusivo gratuito da guilda hostil."}]},{"line":1867,"body":[{"speaker":"Rask","condition":", vitória","expression":"feliz","text":"Resultado confirmado! A equipe de Ghork avança!"}]},{"line":1869,"body":[{"speaker":"Rask","condition":", revés","expression":"neutro","text":"A equipe adversária vence esta luta. Vocês podem pedir revanche. Falem comigo quando estiverem prontos."}]},{"line":1878,"body":[{"speaker":"Rask","condition":"","text":"Nas quartas, a equipe de Ghork enfrenta , com apoio de uma das guildas que já disputaram esta campanha."}]},{"line":1882,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Conseguimos apoio. Investimos no treino. Venha ver o que esse pessoal sabe fazer."}]},{"line":1884,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu nunca duvidei de que vocês soubessem lutar."}]},{"line":1886,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Eu sei. Mas saí daquela reunião sentindo que ainda precisava provar que minha equipe traria todo mundo de volta."}]},{"line":1888,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1890,"speaker":"Ghork","choice":"Eu queria uma reserva de segurança maior para aquele serviço. Não estava dizendo que vocês abandonariam alguém.","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Então deixe nossa luta falar por nós."}],"question":false},{"line":1891,"speaker":"Ghork","choice":"Eu podia ter explicado melhor. Ainda assim, colocaria o dinheiro na reserva.","expression":"neutro","response":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Isso eu aceito. Mas ainda vou tentar ganhar de você."}],"question":false},{"line":1895,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Pagamos pela segurança e mesmo assim chegamos às quartas. Conseguimos apoio e pusemos o treino em dia."}]},{"line":1897,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Não achei que vocês fossem desistir."}]},{"line":1899,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Eu ouvi. Mesmo assim, doeu ver minha reserva de segurança virar algo de que vocês podiam abrir mão."}]},{"line":1901,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1903,"speaker":"Ghork","choice":"Era um reconhecimento limitado. Por isso aceitei uma reserva menor. Eu entendi por que você queria mais.","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Então lembre dessa parte quando contar como foi o serviço."}],"question":false},{"line":1904,"speaker":"Ghork","choice":"Eu devia ter dado mais atenção ao risco que você estava explicando.","expression":"neutro","response":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Devia. Mas, agora, temos uma partida pela frente."}],"question":false},{"line":1908,"body":[{"speaker":"Zagra","condition":"","expression":"neutro","text":"Você passou. Não foi fácil, hein?"},{"speaker":"Ghork","condition":"","expression":"feliz","text":"Não foi mesmo. Vou lembrar dessa luta por um tempo."}]},{"line":1910,"body":[{"speaker":"Darvek","condition":"","expression":"neutro","text":"Você venceu. Vou cuidar da volta do meu pessoal."},{"speaker":"Ghork","condition":"","expression":"neutro","text":"Boa viagem. E obrigado pela luta."}]},{"line":1912,"body":[{"speaker":"Zagra","condition":"","text":"Trouxemos menos do que alguns queriam e o suficiente para esta tentativa. /"},{"speaker":"Darvek","condition":"","text":"Preparar a volta não nos impediu de avançar hoje."}]},{"line":1914,"body":[{"speaker":"Ghork","condition":", revés","text":"Vou me preparar para a revanche. Não vou mudar a história do contrato porque perdi aqui."}]},{"line":1923,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Cinco adversários entre vocês e a final! Talvez já tenham se encontrado pela cidade. Hoje, eles vieram disputar a mesma vaga que vocês."}]},{"line":1925,"body":[{"speaker":"Ghork","condition":", zero aliados","expression":"neutro","text":"Alguns rostos novos. E algumas conversas que ainda não terminaram."}]},{"line":1927,"body":[{"speaker":"Ghork","condition":", com aliados","expression":"neutro","text":"Já conhecemos alguns deles. Não esperem facilidade: eles também querem chegar à final."}]},{"line":1944,"body":[{"speaker":"Ghork","condition":"— resposta ao conjunto","text":""}]},{"line":1946,"speaker":"Ghork","choice":"Vamos fazer uma boa luta. Quero chegar à final tanto quanto vocês.","expression":"feliz","response":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Aos lugares."}],"question":false},{"line":1947,"speaker":"Ghork","choice":"Quero ganhar de vocês. Nem por isso precisamos fingir que nunca nos vimos.","expression":"neutro","response":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Conhecidos ou não, só uma equipe passa. Preparem-se!"}],"question":false},{"line":1951,"body":[{"speaker":"Rask","condition":"","expression":"feliz","text":"A equipe de Ghork está na final!"}]},{"line":1953,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Que luta. Foi bom encontrar vocês de novo. Melhor ainda ganhar."}]},{"line":1957,"body":[{"speaker":"Rask","condition":"","text":"Vitória adversária nesta tentativa. A revanche permanece aberta."}]},{"line":1959,"body":[{"speaker":"Ghork","condition":"","text":"Vocês não facilitaram."}]},{"line":1978,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"neutro","text":"Volte inteiro dessa luta. Quero ver o que vai fazer com todos os dias que vêm depois dela."},{"speaker":"Borun","condition":"papel:Borun","expression":"neutro","text":"Então me conte. Como pretende enfrentar Torvak?"},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"A cidade inteira vai ver você na final. Mostre o que nosso trabalho produziu."}]},{"line":1980,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Quando cheguei, eu pensei... é só ganhar um título, e vão parar de olhar para mim como se eu não servisse para nada."}]},{"line":1982,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"neutro","text":"Talvez alguns nunca enxerguem você como gostaria. Mesmo com esse título."},{"speaker":"Borun","condition":"papel:Borun","expression":"neutro","text":"Torvak tem esse título há anos. Não foi o bastante para ele parar de cobrar reverência dos outros, foi?"},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Podem aceitar o resultado. Isso não significa que todos vão aceitar você."}]},{"line":1984,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":1986,"speaker":"Ghork","choice":"Quero ganhar mesmo assim. Não preciso que você escolha por mim.","response":[],"question":false},{"line":1987,"speaker":"Ghork","choice":"Vou entrar por mim e pelo trabalho que fizemos. Não para encerrar toda discussão.","response":[],"question":false},{"line":1989,"body":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"feliz","text":"Está bem. Vá, então. Eu cuido dos nossos."},{"speaker":"Borun","condition":"papel:Borun","expression":"feliz","text":"Então vá. Não precisa parar para pedir minha aprovação a cada passo."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"neutro","text":"Lembre do que acabou de dizer. Vai precisar sustentar essa posição fora da arena também."}]},{"line":1993,"body":[{"speaker":"Darvek","condition":", se X","expression":"neutro","text":"Aqui está o levantamento completo. Reserva de segurança, custos... tudo registrado, como você pediu."}]},{"line":1995,"body":[{"speaker":"Zagra","condition":", se Y","expression":"neutro","text":"O relatório final aponta o trecho que não verificamos. Ninguém vai dizer que exploramos mais do que de fato vimos."}]},{"line":1997,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Obrigado. Se alguém me dissesse que eu ia ficar feliz de ver um relatório antes da final..."}]},{"line":1999,"body":[{"speaker":"Guedra","condition":"","expression":"feliz","text":"Deixe isso de lado um instante. Pedi para ver sua base, não sua caligrafia."}]},{"line":2001,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Achei que uma vitória ia resolver tudo. Pelo visto, tem uma lista inteira me esperando depois."}]},{"line":2003,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2005,"speaker":"Ghork","choice":"Primeiro, vou ganhar o título. Das outras perguntas eu cuido depois.","expression":"neutro","response":[],"question":false},{"line":2006,"speaker":"Ghork","choice":"Ainda quero ganhar. Só não posso prometer que isso vai resolver tudo.","expression":"neutro","response":[],"question":false},{"line":2008,"body":[{"speaker":"Darvek","condition":"papel:Darvek","expression":"neutro","text":"Está bem. Agora vá se preparar para a luta."},{"speaker":"Zagra","condition":"papel:Zagra","expression":"feliz","text":"Ótimo. Então me prometa uma boa luta."}]},{"line":2010,"body":[{"speaker":"Guedra","condition":"","expression":"neutro","text":"Primeiro, a base. Depois vá quando chamarem."}]},{"line":2014,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Então você chegou. Pena que o general não está aqui para ver."}]},{"line":2016,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Posso lutar sem ele assistindo."}]},{"line":2018,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Aconteça o que acontecer aqui, sua guilda vai usar isso contra mim. Depois de tudo que fiz por esta cidade."}]},{"line":2020,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Você tirou nossos horários de treino porque meu mentor não pediu desculpas. Tentou nos impedir. Chegamos mesmo assim."}]},{"line":2022,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"E acha que isso lhe dá o direito de tomar meu lugar?"}]},{"line":2024,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2026,"speaker":"Ghork","choice":"Vim conquistar o título. Se quiser ficar com ele, vai ter que me vencer.","expression":"neutro","response":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Foi para isso que vim."}],"question":false},{"line":2027,"speaker":"Ghork","choice":"Você já fez seu nome. Vim conquistar o meu.","expression":"neutro","response":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Então chega de falar do meu. Entre na arena."}],"question":false},{"line":2029,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Final do campeonato de guildas de Terminus! Torvak e sua equipe enfrentam a equipe de Ghork!"}]},{"line":2033,"body":[{"speaker":"Torvak","condition":"","text":"“Ainda estou aqui.”"},{"speaker":"Ghork","condition":"","text":"“Eu também. Vou me preparar para voltar.”"},{"speaker":"Rask","condition":"","text":"“A revanche segue disponível.” A conversa de U/V não é repetida nem invalidada; perder uma tentativa não devolve Ghork à exigência de aprovação universal."}]},{"line":2037,"body":[{"speaker":"Rask","condition":"","text":"Resultado confirmado. Ghork e sua equipe vencem o campeonato!"}]},{"line":2043,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2045,"speaker":"Ghork","choice":"Pode repetir? Só mais uma vez.","expression":"feliz","response":[{"speaker":"Rask","condition":"","expression":"feliz","text":"Ghork! Campeão de Terminus!"}],"question":false},{"line":2046,"speaker":"Ghork","choice":"Eu... eu consegui.","expression":"feliz","response":[{"speaker":"Virmura","condition":"papel:Virmura","expression":"feliz","text":"Conseguiu."},{"speaker":"Borun","condition":"papel:Borun","expression":"feliz","text":"Conseguiu. Vá, pode se gabar um pouco. Não vou impedir."},{"speaker":"Sevrak","condition":"papel:Sevrak","expression":"feliz","text":"Você trabalhou por esta vitória. Tire um instante para aproveitar."}],"question":false},{"line":2048,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Eu ouvi. Perdi."}]},{"line":2050,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Eu também ouvi. Você não precisa gostar."}]},{"line":2054,"body":[{"speaker":"Rheed","condition":"","text":"Parte da torcida grita o nome de Ghork até a voz falhar. Outros ainda aplaudem o antigo campeão. Ghork fica mais um pouco na arena, ouvindo os dois lados."}]},{"line":2067,"body":[{"speaker":"Seldan","condition":"","expression":"raiva","text":"Autorizei aquelas entregas, não homens armados! Saiam das saídas. Deixem o público passar!"}]},{"line":2069,"body":[{"speaker":"Dorga","condition":"","expression":"neutro","text":"Mantenham a ordem. A arena fica sob nosso comando até acertarmos as condições com as outras guildas."}]},{"line":2071,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Vocês prepararam isso antes mesmo da nossa luta."}]},{"line":2073,"body":[{"speaker":"Torvak","condition":"","expression":"confuso","text":"Combinamos a tomada da arena. Eu..."}]},{"line":2077,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Soltem essas pessoas! Vocês não falaram nada disso."}]},{"line":2079,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"A produção precisa de gente. E você precisa de outra dose. Cumpra sua parte do acordo."}]},{"line":2081,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Concordei em tomar a arena. Não em entregar meu pessoal para você."}]},{"line":2083,"body":[{"speaker":"Savel","condition":"","expression":"neutro","text":"Vai voltar a pedir. Quando começar a sentir falta da dose."}]},{"line":2085,"body":[{"speaker":"Torvak","condition":"","expression":"raiva","text":"Então vai esperar. Vou tirar essas pessoas daqui."}]},{"line":2089,"body":[{"speaker":"Neral","condition":"","expression":"neutro","text":"Continuem levando os capturados. Quem chegar ao corredor fica por minha conta."}]},{"line":2093,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Tragam os feridos por aqui! Deixem a passagem livre!"}]},{"line":2095,"body":[{"speaker":"Borun","condition":"","expression":"neutro","text":"A saída lateral está livre! Só saio daqui quando o último de vocês passar."}]},{"line":2097,"body":[{"speaker":"Sevrak","condition":"","expression":"neutro","text":"Aprendizes, comigo! Retirem aquele obstáculo. Deixem espaço para quem está passando."}]},{"line":2099,"body":[{"speaker":"Rask","condition":"","expression":"neutro","text":"Sigam as orientações nas saídas! Deixem os pertences. Não voltem para buscar nada!"}]},{"line":2101,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2103,"speaker":"Ghork","choice":"Vou atrás do fornecedor. Mantenham esta passagem livre.","expression":"raiva","response":[{"speaker":"Borun","condition":"","expression":"neutro","text":"Corredor de serviço! Vá por lá. Estamos tirando o público por aqui."}],"question":false},{"line":2104,"speaker":"Ghork","choice":"Quem está cuidando de quem já saiu?","expression":"neutro","response":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Nyra e Jorvi estão com eles. Pirka cuida do transporte. Vá. Encontre quem está dando essas ordens."}],"question":false},{"line":2108,"body":[{"speaker":"Torvak","condition":", ao cruzar Ghork","expression":"neutro","text":"Ele está junto das caixas. Eu tiro essas pessoas daqui."}]},{"line":2110,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Vou atrás dele. Isso não livra você de responder pelo acordo que fez."}]},{"line":2112,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Eu sei."}]},{"line":2116,"body":[{"speaker":"Neral","condition":"","expression":"neutro","text":"Você viu quantas pessoas precisam de mim. Mate o fornecedor, e depois? Acha que a necessidade morre com ele?"}]},{"line":2118,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Vi você usar isso para ameaçar essas pessoas. Depois, mandar arrastar outras à força."}]},{"line":2120,"body":[{"speaker":"Neral","condition":"","expression":"neutro","text":"Quando eu era criança, via as doses irem para quem tinha força ou posição para exigi-las. Então aprendi a produzi-las. Com o tempo, fui eu quem passou a decidir quem recebia."}]},{"line":2122,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2124,"speaker":"Ghork","choice":"E agora faz com eles o que fizeram com você.","expression":"raiva","response":[{"speaker":"Neral","condition":"","expression":"neutro","text":"Agora eu decido. Não pretendo abrir mão disso."}],"question":false},{"line":2125,"speaker":"Ghork","choice":"Solte essas pessoas. Elas não são pagamento.","expression":"raiva","response":[{"speaker":"Neral","condition":"","expression":"neutro","text":"Sem elas, a produção para. É simples assim."}],"question":false},{"line":2129,"body":[{"speaker":"Neral","condition":"","expression":"raiva","text":"Eu criei essas fórmulas. Conheço as doses!"}]},{"line":2131,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Então sabe o que está engolindo."}]},{"line":2133,"body":[{"speaker":"Neral","condition":"","expression":"raiva","text":"Sei o que elas me permitem fazer."}]},{"line":2137,"body":[{"speaker":"Ghork","condition":"","text":"“Ainda não consegui passar.”"},{"speaker":"Borun","condition":", da passagem de evacuação","text":"“Recue por aqui. A saída continua aberta.” A tentativa termina; a ação fica suspensa entre cenas para preparação e acesso ao Coreto. Não corre relógio que mate capturados enquanto o jogador usa o menu. Na retomada,"},{"speaker":"Neral","condition":"","text":"“Voltou para pedir uma dose?”"},{"speaker":"Ghork","condition":"","text":"“Voltei para acabar com isso.” Repetir a tentativa com a transformação preservada. O revés não permite abandonar a campanha ou pular a batalha."}]},{"line":2141,"body":[{"speaker":"Neral","condition":"","expression":"raiva","text":"Acha que isso termina aqui? Existem outros grupos. Em Daratrine... até no Conselho. Teremos este continente antes que vocês descubram por onde entramos."}]},{"line":2143,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Quem? Quem está no Conselho?"}]},{"line":2151,"body":[{"speaker":"Seldan","condition":"","expression":"neutro","text":"Mostre onde encontraram estas cartas. Preciso registrar. Deixem separadas dos materiais que estão retirando."}]},{"line":2153,"body":[{"speaker":"Ghork","condition":"","expression":"confuso","text":"Ele falou no Conselho de Daratrine. É disso que tratam estas cartas?"}]},{"line":2159,"body":[{"speaker":"Seldan","condition":"","expression":"neutro","text":"Os registros conferem. Havia um contato dentro do Conselho. Nada aqui diz quem era."}]},{"line":2161,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Então não temos um nome. Não vou acusar alguém só porque ele quis me assustar antes de morrer."}]},{"line":2163,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Estamos cuidando dos resgatados. Quem tomava as doses dele também precisa de atendimento. A morte dele não acaba com a abstinência."}]},{"line":2174,"body":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Pressionei Rask para cancelar seus treinos. Concordei em tomar a arena. Achei que podia obrigar esta cidade a devolver nosso lugar."}]},{"line":2176,"body":[{"speaker":"Ghork","condition":"","expression":"raiva","text":"Você ajudou a tirá-los de lá. Eu vi. Mas foi o seu acordo que permitiu que aquelas pessoas fossem capturadas."}]},{"line":2178,"body":[{"speaker":"Torvak","condition":"","expression":"triste","text":"Eu sei. Tirar as pessoas de lá não desfaz o que fiz."}]},{"line":2180,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2182,"speaker":"Ghork","choice":"Não estou pronto para perdoar você.","expression":"triste","response":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Não vou pedir que decida isso agora."}],"question":false},{"line":2183,"speaker":"Ghork","choice":"Quero que você responda pelo que fez.","expression":"neutro","response":[{"speaker":"Torvak","condition":"","expression":"neutro","text":"Vou ter que responder."}],"question":false},{"line":2185,"body":[{"speaker":"Virmura","condition":"","expression":"neutro","text":"Primeiro, ele precisa de tratamento. Isso não vai livrá-lo de responder pelo que fez."}]},{"line":2191,"body":[{"speaker":"Lala","condition":"","expression":"confuso","text":"Ghork? Você está bem?"}]},{"line":2193,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Estou vivo. E ganhei o campeonato."}]},{"line":2195,"body":[{"speaker":"Lala","condition":"","expression":"confuso","text":"Você ganhou? Ghork! Espere... por que estar vivo foi a primeira coisa que você disse?"}]},{"line":2197,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Atacaram a festa. Levaram pessoas à força. Conseguimos libertá-las e derrotamos quem comandava, mas... ainda tem feridos. O trabalho não terminou."}]},{"line":2199,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Você ganhou e depois... tudo isso. Vá com calma, Ghork. Estou aqui."}]},{"line":2201,"body":[{"speaker":"Ghork","condition":"— escolha","text":""}]},{"line":2203,"speaker":"Ghork","choice":"Posso contar a final primeiro?","expression":"feliz","response":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Claro. Mas depois quero saber o que aconteceu na festa. Está bem?"}],"question":false},{"line":2204,"speaker":"Ghork","choice":"Primeiro, me conte como você está.","expression":"neutro","response":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Continuo trabalhando nas peças. E, pelo visto, tentando acompanhar você. É muita notícia para uma conversa só."}],"question":false},{"line":2206,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Como vai o trabalho com as peças?"}]},{"line":2208,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Comecei a mostrar para as pessoas. Algumas gostam como estão; outras sugerem mudanças. Estou descobrindo quanto trabalho pode dar até um ajuste pequeno."}]},{"line":2212,"body":[{"speaker":"Lala","condition":", recado de Dam","expression":"neutro","text":"Dam mandou um recado: \"O dinheiro chegou. Compramos parte do material e estamos acertando o resto do reparo. Obrigado por avisar quanto podia mandar.\""}]},{"line":2214,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Parte do material. Ainda está longe da casa que prometi."}]},{"line":2216,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Era disso que ele precisava agora, Ghork."}]},{"line":2220,"body":[{"speaker":"Lala","condition":", recado de Dam","expression":"neutro","text":"Dam mandou um recado: \"Reorganizei o reparo sem contar com seu dinheiro. Ainda falta material. Queria sua ajuda, mas prefiro saber como estão as coisas a continuar esperando. Me conte como você está.\""}]},{"line":2222,"body":[{"speaker":"Ghork","condition":"","expression":"triste","text":"Ganhar não pagou aquele reparo. Eu sei."}]},{"line":2224,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Então conte como você está. Não precisa prometer uma casa inteira para responder isso."}]},{"line":2228,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Quero ficar aqui. Construir minha vida. Já tenho uma vitória para contar, pelo menos... mas, antes de prometer outra coisa, preciso saber como vou cumprir."}]},{"line":2230,"body":[{"speaker":"Lala","condition":"","expression":"feliz","text":"Pode prometer que vai dar notícias. Eu aceito."}]},{"line":2232,"body":[{"speaker":"Ghork","condition":"","expression":"feliz","text":"Essa eu vou cumprir."}]},{"line":2234,"body":[{"speaker":"Ghork","condition":"","expression":"neutro","text":"Tem outra coisa. Encontramos papéis ligando esse grupo ao Conselho. Ainda não sabemos a quem. Eu precisava contar, mas... não deixe que comecem a acusar pessoas sem prova."}]},{"line":2236,"body":[{"speaker":"Lala","condition":"","expression":"neutro","text":"Vou contar o que vocês descobriram. E deixar claro o que ainda não sabem."}]},{"line":2240,"body":[{"speaker":"Rheed","condition":"","expression":"feliz","text":"E assim foi a vitória de Ghork em Terminus. O título era dele. A aprovação de todo mundo, veja bem, não. Mas o título era dele."}]},{"line":2242,"body":[{"speaker":"Criança","condition":"— escolha","text":""}]},{"line":2244,"speaker":"Criança","choice":"Depois ele foi para Daratrine?","expression":"confuso","response":[{"speaker":"Rheed","condition":"","expression":"neutro","text":"Este conto termina em Terminus. Aqueles papéis vão ter que esperar outra conversa."}],"question":false},{"line":2245,"speaker":"Criança","choice":"Ele ainda queria ser um grande mercenário?","expression":"confuso","response":[{"speaker":"Rheed","condition":"","expression":"feliz","text":"Ah, queria. Os sonhos não tinham acabado. Só aprendeu a pensar um pouco mais antes de prometer uma casa a alguém."}],"question":false},{"line":2247,"body":[{"speaker":"Rheed","condition":"","expression":"feliz","text":"Pronto. Já posso guardar o frasco. A noite dele também foi movimentada."}]}]};
